  const kelinData = [{"id":"0885d017-0781-4f0b-9f0a-5fe3f4146c2d","slug":"optional-mechanics","title":"Опциональная механика","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Механика","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", которую в рамках рассматриваемой цели можно исключить и всё ещё выполнить цель","type":"text"}]},{"type":"paragraph","content":[{"text":"Можно ли её исключить или нет, определяется через ","type":"text"},{"text":"рационального агента","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"c42ca45f-d2a9-4c7a-a70a-1128884058c2","slug":"gameplay-collapse","title":"Геймплей схлопнулся","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Ситуация, при которой комплексные системы схлопываются до тривиальных выводов, ввиду чего ресурсы, затраченные на разработку этих систем, оказались потрачены впустую","type":"text"}]}]}},{"id":"69864bb9-f53e-4a82-901f-d4f26732e501","slug":"difficulty","title":"Сложность","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Произведение вероятности совершить ошибку на цену этой ошибки","type":"text"}]}]}},{"id":"6f5a8925-4e48-4702-a6d1-7e50ca59b525","slug":"kelvin-moment","title":"Кельвин moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Требование проведения экспериментов, сбора статистики и прочих научных подтверждений таким тривиальным вещам как ","type":"text"},{"text":"\"нажатие трёх кнопок требует бОльших усилий, чем нажатие двух\"","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"См. ","type":"text"},{"text":"Видео Того Самого Келина не научны","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/nPwhWU0R29I","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}},{"id":"d1674b9f-2e05-4fb6-a94d-acf69a17170f","slug":"potential-challengeness","title":"Потенциальная челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Общая челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#general-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" - ","type":"text"},{"text":"реализованная","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Иными словами, то, что могло в игре быть, но этого нет","type":"text"}]}]}},{"id":"a2624356-ee3d-44ee-adc0-e3b12e571e48","slug":"realized-challengeness","title":"Реализованная челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Измеряется фактически существующими в игре ","type":"text"},{"text":"челленджами","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"5f626c81-fa38-40dc-b945-8438bd1d93c9","slug":"minmaxing","title":"Минмаксинг","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Стратегия, при которой игрок максимизирует одни аспекты ","type":"text"},{"text":"(например, урон)","type":"text","marks":[{"type":"italic"}]},{"text":", игнорируя или жертвуя другими, менее важными ","type":"text"},{"text":"(например, защита от огня)","type":"text","marks":[{"type":"italic"}]}]}]}},{"id":"8fd66ff1-0334-4c0c-bb68-417d7f9f7669","slug":"dark-meta","title":"Dark Meta","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Вид мета-прогрессии в рогаликах, при котором изначально игра более сложная (иногда непроходимо сложная), но по мере перманентной прокачки становится проще и проще","type":"text"}]}]}},{"id":"d359253f-419b-4b93-a60c-ea5c4d27d7a3","slug":"mechanics-in-vacuum","title":"Полезность механики зависит от контекста","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Механики в вакууме не являются ни плохими, ни хорошими. Они становятся таковыми, лишь находясь в контексте, в сочетании с другими существующими решениями. Создаёт ли это решение новый игровой опыт или же ломает то, что построено остальными механиками? Вот в чём вопрос","type":"text"}]}]}},{"id":"11f255db-4742-407e-a3e8-10d8a10afdfa","slug":"general-challengeness","title":"Общая челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Определяется всеми ","type":"text"},{"text":"челленджами","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", которые возможны из описания игровых механик. Независимо от того, представлены они в игре или нет, форсит ли игра их выполнять или нет итд.","type":"text"}]}]}},{"id":"02555c29-1687-4c2b-bbfb-02c917dabd95","slug":"challenge","title":"Челлендж","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Любая задача, требующая от игрока применения определённого навыка и допускающая вероятность ошибки","type":"text"}]}]}},{"id":"c4814ee8-1861-477e-9028-ccd6cc244bd4","slug":"there-is-that-thing","title":"В игре есть, в игре можно","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Само по себе ","type":"text"},{"text":"\"в игре есть\"","type":"text","marks":[{"type":"italic"}]},{"text":" не является буллшитом, но зачастую люди приводят в контраргумент штуки, которые ничего не меняют","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, существование в ","type":"text"},{"text":"Gunfire Reborn","type":"text","marks":[{"type":"bold"}]},{"text":" перка на 3 дэша не отменяет того, что базовая мобильность персонажа крайне мала, а вся боевая система дизайнится с расчётом на базового персонажа, а не под этот перк - ведь он может не выпасть, и игра должна быть проходима без него","type":"text"}]},{"type":"paragraph","content":[{"text":"Также часто приводят и ","type":"text"},{"text":"иррациональные штуки","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", ","type":"text"},{"text":"опциональные механики","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" итд","type":"text"}]},{"type":"paragraph","content":[{"text":"Поэтому будьте внимательны - как минимум, если хочется такое написать, вместо утверждения с порога лучше спросить ","type":"text"},{"text":"\"а что насчёт X?\"","type":"text","marks":[{"type":"italic"}]},{"text":". Скорее всего, X не упомянулся по вышеописанной причине","type":"text"}]}]}},{"id":"38f4fc3e-d006-42d4-91b8-6bc1ef88bd74","slug":"dyssynergy","title":"Диссинергия","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Воздействие двух элементов друг на друга таким образом, что их объединённый эффект ниже, чем по отдельности","type":"text"}]},{"type":"paragraph","content":[{"text":"Например","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"+5 к урону, но -5 к скорости атаки\" аннулирует \"+5 к скорости атаки, но -5 к урону\". Тогда как последний, к примеру, можно было использовать в ","type":"text"},{"text":"синергии","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#synergy","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" с on-hit эффектами","type":"text"}]}]}]}]}},{"id":"eb17db77-d69f-4d6f-91dc-5701b24ca194","slug":"people-are-used-to-it","title":"Люди уже привыкли","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"То, что люди привыкли к той или иной проблеме - не значит, что этой проблемы нет.","type":"text"}]},{"type":"paragraph","content":[{"text":"Пример:","type":"text","marks":[{"type":"bold"}]},{"text":" в ","type":"text"},{"text":"Dead Cells","type":"text","marks":[{"type":"bold"}]},{"text":" некоторые мобы иногда ломают поведение при парировании. Если игрок этого не знает, он может из-за этого заруинить забег. К этому можно привыкнуть, но это не значит, что проблемы нет и что её нельзя пофиксить","type":"text"}]}]}},{"id":"9e158fa2-3f9e-433c-8420-87e5db2f25dc","slug":"this-game-is-about-x","title":"Эта игра про X","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Тейк \"игра про Х\" в большинстве случаев используется людьми в следующих целях:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Понизить планку оценивания до уровня, когда игра до неё начинает дотягивать, не желая признавать, что игра может быть гораздо большим","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Выставить один из аспектов игры, который человеку понравился за ключевой, игнорируя то, что это комплексный продукт, а аудитория не ограничивается этим человеком","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"При критике одного аспекта переключаться на другой, где якобы проблем нет, при разборе следующего аспекта переключаться ещё куда-то - и так, пока не уйдём в луп","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игра про всё, что в ней есть","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"http://localhost:5173/glossary#games-as-a-whole","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разбор Elden Ring с разных перспектив","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/LoLljYUofWM","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"b1b591f3-f066-4203-bcf9-86dbeadeca2e","slug":"did-not-happen-for-me","title":"У меня не было","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Общая формула такого коммента: ","type":"text"},{"type":"hardBreak"},{"text":"%объективное_утверждение% говно, потому что %субъективное_обоснование%","type":"text","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"text":"Ваш личный опыт - это ваш личный опыт. Если вам повезло не столкнуться с проблемой - это не значит, что других она не коснулась. И не значит, что люди, у которых опыт получился негативным, являются криворукими дураками или типа того","type":"text"}]},{"type":"paragraph","content":[{"text":"В своём анализе я описываю свойства игры и что из них следует. Это не значит, что часть про \"следует\" произойдёт абсолютно с каждым игроком, но это может произойти, а посему есть смысл прикинуть, как сделать лучше","type":"text"}]}]}},{"id":"60dd9a91-3e54-4c1f-bc84-8efb7fe43bde","slug":"games-as-a-whole","title":"Игра - не про X, Y или Z. Она про всё","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Часто, когда анализируется тот или иной аспект в крупной игре, приходят люди и говорят \"эта игра не про боёвку, она про билдострой\". Потом разби��ается билдострой, приходят другие и говорят \"эта игра не про билды, она про эксплоринг\". И так пока круг не замкнётся","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот, в своём анализе я отталкиваюсь от того, что игра - про всё, что в ней есть","type":"text"}]},{"type":"paragraph","content":[{"text":"Одно дело, когда в игре, скажем, отсутствует боёвка. Возьмём к примеру условный рогалик ","type":"text"},{"text":"Megaloot","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2440380/Megaloot/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - здесь у нас буквально идёт автобой. Будет неразумно называть проблемой отсутствие каких-нибудь активных кнопок с необходимостью ими как-то жонглировать и т.д. Это, возможно, было бы неплохо заиметь, но здесь боёвки буквально нет. Разработчик не тратил на это ресурсы, поэтому вопросов нет","type":"text"}]},{"type":"paragraph","content":[{"text":"Совсем другое дело, когда в игре присутствует выраженная боевая система с продвинутыми интеракциями скиллов - такое стоит анализировать. И если какой-то из продвинутых аспектов проседает, либо одно аннулирует другое ","type":"text"},{"text":"(что является регулярной историей, например, в тех же диаблоидах, где билдострой аннулирует боёвку)","type":"text","marks":[{"type":"italic"}]},{"text":", то это нужно разбирать и искать варианты, как улучшить, а не говорить \"это игра про другое\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Если в игре какой-то аспект хромает, и подавляющее большинство игроков действительно считает, что игра действительно не про это, то налицо впустую потраченные разработчиком ресурсы, которые только отвлекают от той самой \"сути\". Соответственно, этот аспект нужно либо как-то фиксить и дорабатывать, чтобы люди перестали считать это рудиментом и пытаться нивелировать его присутствие, либо выкидывать его целиком","type":"text"}]},{"type":"paragraph","content":[{"text":"Так, например, я категорически не согласен с позицией ","type":"text"},{"text":"\"диаблоиды - игры про райтклик\"","type":"text","marks":[{"type":"italic"}]},{"text":". Студии вкладывают огромное количество денег в проработку механической составляющей скиллов - их разнообразие, взаимодействие итд, чтобы потом дядя Вася сказал ","type":"text"},{"text":"\"где мой фликер страйк, мне эта дрочка кнопок не упала\". ","type":"text","marks":[{"type":"italic"}]},{"text":"Соответственно, у диаблоидов в рамках позиции \"игра - про всё\" есть два пути","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"либо дорабатывать боёвку, как я предлагал ","type":"text"},{"text":"в обзоре Path of Exile 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/HA-yrnl7sKc?si=IA1WAipcVxsOWCbq","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"либо принять эту позицию и делать что-то в духе ","type":"text"},{"text":"Vampire Survivors","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1794680/Vampire_Survivors/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", только с картами и продвинутой, продолжительной прогрессией. Вампиры с закосом под Diablo, к слову, ","type":"text"},{"text":"уже существуют","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2218750/Halls_of_Torment/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - осталось прогрессию подтянуть","type":"text"}]}]}]}]}},{"id":"f812da7e-1b6a-402d-b930-285b544699ce","slug":"exploits-are-actually-good","title":"\"Абузы\" - окна для интересного геймплея","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Если в игре что-то выглядит как абуз, то прежде, чем это \"фиксить\", стоит подумать - а можно ли это как-то обыграть?","type":"text"}]},{"type":"paragraph","content":[{"text":"Нередко такие штуки могут создать уникальный геймплей, а попытки их \"забалансить\" результируют в шаблонном продукте","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Не забирай у игроков свободу выбора","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/shorts/um7QZeA7CDY","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"1bb576bb-76f0-45d5-9ef5-e33e255b8498","slug":"i-have-another-definition","title":"У меня другие определения","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Иногда люди пишут, что кто-то несёт лютую ахинею, а затем выясняется, что у них своё определение слов. Да даже не \"своё\", а в целом другое, не соответствующее тому, которое использовал собеседник","type":"text"}]},{"type":"paragraph","content":[{"text":"Рассуждения строятся в рамках той терминологии, которая обозначена утверждающим. Соответственно, корректность выводов нужно оценивать в рамках заданной терминологии","type":"text"}]},{"type":"paragraph","content":[{"text":"Если термин не обозначен и не выводится однозначно из утверждений, то перед этим стоит спросить, что человек имеет в виду под словом X. А не сразу бросаться говорить ему, какой он дурак","type":"text"}]},{"type":"paragraph","content":[{"text":"Изобретать свои термины для удобства, к слову - абсолютно нормально. Так, например, даже слово \"гравитация\" у того же Ньютона и Эйнштейна имеет абсолютно разное значение. Если вы не готовы это принять, то дискуссия с вами невозможна, и единственное, что получится из коммуникации - многочасовой срач за определения, который ни к чему не приведёт","type":"text"}]}]}},{"id":"7147a972-76bb-49da-80bf-a0c4041fa792","slug":"it-has-always-been-like-that","title":"В прошлой части/игре/других играх жанра так было","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"То, что где-то что-то когда-то было, не значит, что это хорошо","type":"text"}]},{"type":"paragraph","content":[{"text":"И даже если к этому привыкли, это не значит, что так и должно быть дальше","type":"text"}]},{"type":"paragraph","content":[{"text":"Чаще всего данной фразой оправдывают наличие каких-либо хреновых решений, называя их ","type":"text"},{"text":"\"наследие серии\", \"сутью жанра\"","type":"text","marks":[{"type":"italic"}]},{"text":" итд","type":"text"}]},{"type":"paragraph","content":[{"text":"Быть консерватором в такой молодой индустрии, как видеоигры - зашквар. Если бы разработчики придерживались таких тейков, то мы бы до сих пор играли только в ретро-платформеры и ASCII-рогалики. Ибо каждый качественный скачок вперёд всегда сопровождался фразой ","type":"text"},{"text":"\"а что, если\"","type":"text","marks":[{"type":"italic"}]},{"text":" или ","type":"text"},{"text":"\"нахрена оно вот так, если можно вот так и будет лучше\"","type":"text","marks":[{"type":"italic"}]}]}]}},{"id":"b00f757e-5d59-4502-a30f-4c8fbd142405","slug":"i-see-that-author-is-retarded","title":"Сразу видно, автор...","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Критикуй конкретные утверждения, а не додумывай, почему автор что-то сказал","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Хорошо: ","type":"text"},{"text":"\"этот противник получает повышенный урон от рипоста, так что его можно не ковырять долго вилкой\"","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Плохо: ","type":"text"},{"text":"\"сразу видно, автор никогда не играл в подобные игры и посему несёт бредик про ковыряние вилкой\"","type":"text","marks":[{"type":"italic"}]}]}]}]},{"type":"paragraph","content":[{"text":"Последнее - инста бан без прочтения. Подобные комментарии не только бессодержательны и тратят впустую время на токсины, но и в большинстве случаев не соответствуют действительности, поскольку выводы об авторе строятся лишь из того, что человек успел увидеть бегло в профиле канала (если вообще его смотрел)","type":"text"}]}]}},{"id":"08e26ca1-d4ff-4641-ab99-6d9204eb935a","slug":"subjectivity","title":"Всё субъективно, объективности не существует","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Во-первых, если вы считаете, что ","type":"text"},{"text":"\"всё в нашем мире субъективно\"","type":"text","marks":[{"type":"italic"}]},{"text":", то вы ","type":"text"},{"text":"дифичент","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/M6vD-iLc_PI?t=62","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}},{"type":"bold"}]},{"text":", поскольку уже сама фраза ","type":"text"},{"text":"\"всё субъективно\"","type":"text","marks":[{"type":"italic"}]},{"text":" содержит в себе парадокс","type":"text"}]},{"type":"paragraph","content":[{"text":"Если всё субъективно, то и само это утверждение тоже. А это либо так, и тогда субъективизм несостоятелен; либо не так - и тогда это неверное утверждение","type":"text"}]},{"type":"paragraph","content":[{"text":"С субъективным подходом невозможно сделать ни один полезный вывод. Если бы всё в нашем мире было субъективно, то в нём царил бы полный хаос. Однако же, мы живём в обществе, которое как-то структурировано; мы имеем науку, которая, хоть и имеет дыры в некоторых вопросах, работает безотносительно нашего мнения; мы имеем такую штуку как ","type":"text"},{"text":"\"статистика\"","type":"text","marks":[{"type":"italic"}]},{"text":" и ","type":"text"},{"text":"\"теория вероятности\"","type":"text","marks":[{"type":"italic"}]},{"text":" итд.","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему, доля субъективных утверждений минимизируется, а приоритет отдаётся логике и фактом","type":"text"}]},{"type":"paragraph","content":[{"text":"Ну и наглядно разницу между \"субъективно\" и \"объективно\"","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Субъективно: ","type":"text","marks":[{"type":"bold"}]},{"text":"Мне не понравилась %штука_нейм%","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Объективно: ","type":"text","marks":[{"type":"bold"}]},{"text":"%штука_нейм% содержит %противоречие_нейм% и делает %такой_то_геймплей% невыгодным","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Субъективно:","type":"text","marks":[{"type":"bold"}]},{"text":" Я играл ","type":"text"},{"text":"%вот так-то%","type":"text","marks":[{"type":"italic"}]},{"text":" и остался недоволен","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Объективно: ","type":"text","marks":[{"type":"bold"}]},{"text":"%штука_нейм%","type":"text","marks":[{"type":"italic"}]},{"text":" и ","type":"text"},{"text":"%другая_штука_нейм%","type":"text","marks":[{"type":"italic"}]},{"text":" приводят к тому, что игрок с бОльшей вероятностью будет играть ","type":"text"},{"text":"%вот так-то%","type":"text","marks":[{"type":"italic"}]}]}]}]}]}},{"id":"399eb820-3c2b-470b-b7b6-ae572c366c68","slug":"but-the-game-is-selling","title":"Но ведь игра продаётся","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Качество продукта и его некое \"логическое, геймдизайнерское совершенство\" являются лишь одним из компонентов, влияющих на коммерческий успех","type":"text"}]},{"type":"paragraph","content":[{"text":"Сюда также относится:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Другие составляющие, такие как сюжет, графика итд.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Востребованность таких игр на рынке. Например, даже самые пососные сурвайвал-игры разлетаются как горячие пирожки, несмотря на то, что сделаны на коленке и делают то же самое, что десяток подобных проектов до этого","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Отсутствие конкуренции. Почти как прошлый пункт, но чуть с другой стороны. Если у людей есть интерес к чему-то, но при этом нет достойных проектов, то и такой себе проект люди охотно купят","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Маркетинг. Сюда входит как активная реклама, так и просто ","type":"text"},{"text":"\"это игра от создателей Dark Souls\"","type":"text","marks":[{"type":"italic"}]},{"text":" или ","type":"text"},{"text":"\"это вампиры по Deep Rock Galactic\"","type":"text","marks":[{"type":"italic"}]},{"text":". Cyberpunk 2077, к слову, продался в рекордных количествах, несмотря на то, что его релизное состояние было отвратительным","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Факторы, которые в отдельно взятом обсуждении могли не рассматриваться, т.к. фокус был на чём-то конкретном. К примеру, ","type":"text"},{"text":"\"разбор боёвки без билдостроения\"","type":"text","marks":[{"type":"italic"}]},{"text":" или ","type":"text"},{"text":"\"первый взгляд без разбора эндгейма\"","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"и ещё куча других факторов","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Посему нет смысла говорить \"игра продалась, значит, критика геймдизайна идёт лесом\"","type":"text"}]}]}},{"id":"ba442f11-25bb-45cc-9222-d59bb066c53d","slug":"criticism-should-be-constructive","title":"Критика должна быть конструктивной","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Многие люди при слове \"критика\" представляют ворчащего деда, который вечно всем недоволен","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот, критика - не об этом","type":"text"}]},{"type":"paragraph","content":[{"text":"Критика должна нести в себе конструктивную цель. Если поднимается какая-то проблема - нужно не просто говорить ","type":"text"},{"text":"\"это плохо\"","type":"text","marks":[{"type":"italic"}]},{"text":", но и предложить возможные решения. Если идей по улучшению нет - то хотя бы пригласить остальных к диалогу","type":"text"}]},{"type":"paragraph","content":[{"text":"То же самое касается и критики критики","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Если вы считаете, что предложенные решения чем-то плохи - предложите лучше или хотя бы расскажите, что именно вас смущает и почему","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Если вы считаете, что какой-то из здесь перечисленных основополагающих принципов приводит к ложным выводам или в принципе обладает недостаточной предсказательной силой - предложите лучше или расскажите, почему","type":"text"}]}]}]}]}},{"id":"4b5a45a2-11c1-4400-b422-14d0b9c78d0b","slug":"cooperative-types","title":"4 вида кооператива","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Сразу ","type":"text"},{"text":"важные ","type":"text","marks":[{"type":"bold"}]},{"text":"оговорки:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"“Виды кооператива” — это короткая формулировка, которая сразу дает понять, что ","type":"text"},{"text":"речь именно про взаимодействие с тиммейтами","type":"text","marks":[{"type":"bold"}]},{"text":". Такое взаимодействие может быть не только в кооперативе, но и мультиплеере, главное, чтобы были тиммейты","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ни один из видов не лучше и не хуже других","type":"text","marks":[{"type":"bold"}]},{"text":". При этом каждый из вариантов можно сделать плохо или хорошо. Причем вот это плохо/хорошо достигается разными способами","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разные виды коопов нравятся разным людям","type":"text","marks":[{"type":"bold"}]},{"text":", это нормально. Такая классификация в том числе помогает понимать, а что нравится вам, и как это понятно объяснить остальным","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Для всех видов кооператива важно не забывать, что ","type":"text"},{"text":"геймплей каждого конкретного игрока должен быть интересен","type":"text","marks":[{"type":"bold"}]},{"text":". Это может быть незаметно за общей комплексностью, но если чей-то игровой опыт по итогу уныл, примитивен и репитативен — это очень серьезная проблема. ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В играх часто сочетаются разные виды кооперативных взаимодействий, как чередованием, так и комбинированием. Поэтому ","type":"text"},{"text":"зачастую корректнее характеризовать конкретные сегменты","type":"text","marks":[{"type":"bold"}]},{"text":" ","type":"text"},{"text":"игры ","type":"text","marks":[{"type":"bold"}]},{"text":"отдельно друг от друга. Всю игру целиком можно описать, если этот вид коопа в ней очевидно основной или вообще единственный","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Сами виды:","type":"text"}]},{"type":"paragraph","content":[{"text":"Совместная игра","type":"text","marks":[{"type":"bold"}]},{"text":" — вы вместе играете в одну игру, разделяя ","type":"text"},{"text":"общий контекст и влияя на один и тот же мир","type":"text","marks":[{"type":"bold"}]},{"text":", возможно даже напрямую помогая другим игрокам, но не имеете необходимости как-то коммуницировать или активно следить за тиммейтами","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Division 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2221490/Tom_Clancys_The_Division_2/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Deep Rock Galactic","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/548430/Deep_Rock_Galactic/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spiritfarer","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/972660/Izdanie_Spiritfarer_Farewell/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если наличие тиммейтов дает свой импакт и он велик.","type":"text"},{"type":"hardBreak"},{"text":"Например:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Можно играть активнее и агрессивнее за счет разделения агра и ответственности","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Увеличено разнообразие билдов, за счет возможности разделения боевых задач и помощи другим тиммейтам. Есть разного рода саппорт-билды и билды, специализирующиеся на убийстве конкретных категорий мобов","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ты регулярно видишь и пользуешься результатами чужих трудов за счет того, что действия других игроков изменяют игровой мир","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игра активно подкидывает вам почву для обсуждений и комментариев, за счет поднимания каких-то тем в сюжете, создания вау моментов, смены сеттинга и множества отсылок","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Командная игра","type":"text","marks":[{"type":"bold"}]},{"text":" — вы ","type":"text"},{"text":"активно следите за своими тиммейтами","type":"text","marks":[{"type":"bold"}]},{"text":", за тем где они, что делают, что пытаются сделать, и ","type":"text"},{"text":"на основе этой информации сами принимаете решения","type":"text","marks":[{"type":"bold"}]},{"text":", как вам лучше отыгрывать","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helldivers 1","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/394510/HELLDIVERS_Dive_Harder_Edition/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Marvel Rivals","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2767030/Marvel_Rivals/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"ibb & obb","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/95400/ibb__obb/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если всем игрокам нужно следить за действиями друг друга и делать это нужно действительно активно.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры задач:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Правильно позиционироваться друг относительно друга: например нужно быть рядом, быть с правильной стороны, не перекрывать прицел, не подходить слишком близко, вовремя сходиться и расходиться, параллельно с этим куда-то двигаться","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Вовремя сейвить друг друга, например: накидывать барьер или закрывать щитом/грудью за секунду до потенциальной смерти, сбивать опасные проджектайлы, откидывать врага от тиммейта или наоборот в опасные моменты","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Одновременно атаковать одни и те же цели","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Намеренно не атаковать ту же цель, что и тиммейт, если это ему помешает. ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Использовать способности отталкивания, притягивания и другого передвижения противника, помогая тиммейтам, а не мешая им ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Не перекрывать способности друг друга, например не кидать свой стан, если видишь, что тиммейт ближе и из-за этого кинет свой стан раньше","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Бафать друг друга в момент, когда это будет наиболее эффективно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Коллаборативное взаимодействие","type":"text","marks":[{"type":"bold"}]},{"text":" — вы коммуницируете для ","type":"text"},{"text":"совместного принятия решений","type":"text","marks":[{"type":"bold"}]},{"text":" в игре ","type":"text"},{"text":"или для предложения каких-то внутри-игровых взаимодействий","type":"text","marks":[{"type":"bold"}]},{"text":". Проще говоря, вы обсуждаете или предлагаете дальнейшие действия в игре","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Divinity: Original Sin 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/435150/Divinity_Original_Sin_2__Definitive_Edition/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rabbit and Steel","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2132850/Rabbit_and_Steel/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"PlateUp!","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1599600/PlateUp/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если обсуждать и предлагать дальнейшие действия нужно часто, а итоговые решения и внутри-игровые взаимодействия значимы и интересны","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры задач:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Обсудить на какой квест пойти","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Обсудить как лучше прокачаться и закупиться, потенциально даже сначала предложив разойтись по разным торговцам, чтобы сразу видеть все варианты, что купить","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Придумать план по обкрадыванию торовца, распределив задачи, кто будет отвлекать жертву и потом даст себя осмотреть, кто будет отвлекать других NPC, чтобы они отвернулись или не дошли до места кражи, и кто сворует нужный лут, а потом сбежит с места преступления","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Придумать решение боевого или логического паззла","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Быстро заколлить что-то (от слова колл — призыв к действию). Например убийство, лечение, пуш, отступление или выбивание конкретных способностей из противника","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Сервисное общение","type":"text","marks":[{"type":"bold"}]},{"text":" — вы имеете разную информацию о ситуации в игре и коммуницируете, либо чтобы ","type":"text"},{"text":"лучше понять ситуацию","type":"text","marks":[{"type":"bold"}]},{"text":", либо чтобы дать ","type":"text"},{"text":"прямые инструкции","type":"text","marks":[{"type":"bold"}]},{"text":" для прохождения какого-то сегмента","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Keep Talking and Nobody Explodes","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/341800/Keep_Talking_and_Nobody_Explodes/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"We Were Here","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/bundle/12260/We_Were_Here_Series/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если хорошо обыграно само общение в моменты объяснения ситуации, передачи и выполнения инструкций","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры обыгрывания:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно быстро объяснять нестандартные сложные символы, из-за чего приходится подбирать потенциально забавные ассоциации","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно точно сообщить слово, но у него есть много созвучных вариантов. (пОроГ - пОроК - пАроК, итак - и так, ещЕ раз - ещЁ раз)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно сообщить об отсутствии слова на табло, но также могут быть варианты “НИЧЕГО”, “ПУСТО”, “ЭКРАН” ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В прямую инструкцию вроде “Напиши X” встраивается слово, которое может быть воспринято, как продолжение инструкции — “Напиши ЕЩЁ РАЗ”","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно объяснить очень странную картину, но на ней важно сразу множество деталей и объяснения вроде “Птица с панцирем улитки на спине”, будет недостаточно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"4 вида кооператива в играх","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/dM6yBonVR3A","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"c42d8596-a8ed-4917-a8e9-3f176584d295","slug":"game-properties-over-subjective-experience","title":"Свойства игры > личный опыт","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"При разборе гейм-дизайна следует отталкиваться от самих свойств игры и смотреть, что из них следует, а не от того, как в игру играл отдельный игрок","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, если в игре с огромным количеством развилок в одной из них находится очень важный для прохождения предмет, без которого игровой опыт будет значительно хуже - это проблема. Если кому-то в такой игре повезло пойти в правильную развилку, это не отменяет того, что есть огромная вероятность пойти в неправильную и заруинить себе прохождение","type":"text"}]},{"type":"paragraph","content":[{"text":"Также стоит разграничивать фидбек, причина которому лежит в отдельно взятом индивиде, от фидбека, причина которому лежит в самой игре","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, если при наличии открытого коридора перед глазами отдельно взятый игрок шёл в стену 20 часов и сказал \"игра скучная\" - этот фидбек нерелевантен. Если же сама игра спрятала нужный проход где-то в тени, и игрок не понял, куда идти - это проблема игры. И, скорее всего, такой фидбек будет массовым","type":"text"}]}]}},{"id":"c0c326c6-5ad8-41c3-9ba9-4aeebce48ee2","slug":"game","title":"Игра","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"В контексте рассуждений и дальнейших определений под играми понимается форма медиа, представляющая собой интерактивное развлечение, которое ставит перед игроком различные задачи, выполняемые посредством заданных правил и ","type":"text"},{"text":"механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", позволяющих взаимодействовать с игровым миром в широком смысле (то есть стол в карточной игре — тоже игровой мир), и вознаграждает за выполнение этих задач","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Это определение призвано лишь пояснить область рассуждений и их применимости. Оно не является идеальным исчерпывающим набором критериев для определения, что игрой является, а что нет","type":"text"}]}]}},{"id":"c8ae4569-90d7-46e1-9ec1-aa122f4a2eb0","slug":"challengeness","title":"Челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Метрика, которая характеризуется количеством уникальных ","type":"text"},{"text":"челленджей","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в игре","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Общая челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#general-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Реализованная челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Потенциальная челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#potential-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"c6526fb0-c836-4d8a-a3f3-ecfa25376f51","slug":"rational-agent","title":"Рациональный агент","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Абстрактный агент, действующий оптимальным образом для достижения результата в рамках рассматриваемой цели","type":"text"}]},{"type":"paragraph","content":[{"text":"Стоит отметить ряд моментов","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Рациональный агент применяется к заданной интересующей цели, а не обязательно к одному лишь общему \"пройти игру\". Так, например, в условной DmC люди не ставят задачей \"просто пройти игру\", они ставят задачу \"пройти игру красиво\". Соответственно, анализировать рациональность нужно в рамках этой задачи","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Рациональный агент - не всезнайка. Если какая-то информация на момент принятия решения недоступна, нельзя учитывать её в расчётах","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Рациональность учитывает не только сухую эффективность, но и сложность исполнения, освоения итд. Т.е. если действие X даёт в 10 раз бОльший результат, чем Y, но при этом X сопоставимо сложнее исполнить, то рациональность этих двух действий равна","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Стоит, однако, отметить, что при математически равной рациональности игроки, скорее всего, отдадут предпочтение более стабильной стратегии","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также ","type":"text"},{"text":"3 типа рациональности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rationality-types","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"bc7eac1d-b2d6-4c1f-b0fe-e08dbac29c3c","slug":"orthogonality","title":"Ортогональность","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Свойство элементов игры, означающее их независимость друг от друга","type":"text"}]},{"type":"paragraph","content":[{"text":"Представим две игровые системы в качестве осей X и Y, значения которых характеризуют утилизацию этих игровых систем","type":"text"}]},{"type":"paragraph","content":[{"text":"Для достижения успеха игрок должен дойти до определённой пороговой зоны, которая, начинается, скажем, с точки (3; 2)","type":"text"}]},{"type":"paragraph","content":[{"text":"Если игровые системы ортогональны по отношению друг к другу, это означает, что игрок не сможет добраться до этой зоны, замастерив лишь одну систему","type":"text"}]},{"type":"paragraph","content":[{"text":"Данная концепция полезна при проектировании. Если задачей разработчика стоит не допустить аннулирование, скажем, боевой системы билдостроением, то в эти системы сразу стоит закладывать ортогональные ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Примеры ортогональности:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок мог бы пройти игру чисто на скилле, научившись идеально избегать атак противников. Однако, враги спавнятся с определённым интервалом, а по мере забега становятся жирнее. Из-за чего, если игрок игнорирует билдостроение, то он перестанет успевать зачищать мобов и его задавит числом","type":"text"}]}]}]}]}},{"id":"500acada-5524-4a84-ab44-a2029afccb94","slug":"games-are-about-gameplay","title":"Геймплей первичен","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Геймплей - ключевой аспект ","type":"text"},{"text":"игр","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#game","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", отличающий их от других форм медиа","type":"text"}]},{"type":"paragraph","content":[{"text":"Именно качество реализации геймплея определяет, насколько полученный продукт хорош, как игра","type":"text"}]},{"type":"paragraph","content":[{"text":"Это не означает, что остальные факторы, вроде графики, сюжета и т.д. не важны. Это значит, что любой, даже чисто сюжетной игре, нужно в полной мере использовать геймплей","type":"text"}]},{"type":"paragraph","content":[{"text":"Этот принцип касается не только \"сугубо геймплейных\" жанров вроде рогаликов и метроидваний, но и в том числе тех, что ориентированы на нарратив","type":"text"}]},{"type":"paragraph","content":[{"text":"В контексте нарратива геймплей является очень сильным инструментом для донесения какого-либо опыта, чувств итд.","type":"text"}]},{"type":"paragraph","content":[{"text":"В то время как книги и фильмы предлагают тебе просто наблюдать за происходящим, игры позволяют тебе это прочувствовать на себе, непосредственно проживать и испытывать, как минимум на уровне принятия решений","type":"text"}]},{"type":"paragraph","content":[{"text":"Если же сюжетно-ориентированная игра строится по принципу ","type":"text"},{"text":"“игры - это кино, где геймплей выступает в качестве экшн-сцен”","type":"text","marks":[{"type":"italic"}]},{"text":", то эта игра не пользуется сильнейшим доступным инструментом воздействия на игрока в полной мере, и по итогу плоха, как игра","type":"text"}]},{"type":"paragraph","content":[{"text":"Игра с плохим геймплеем, но хорошим сюжетом - это всегда упущенный потенциал","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры использования геймплея для усиления нарратива: ","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"It Takes Two","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1426210/It_Takes_Two/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" в нашумевшем фрагменте со слонихой заставляет игроков своими руками несколько раз её разорвать, несмотря на вопли и мольбы остановиться. И это не просто разовый выбор в диалоге с катсценой после - это именно длящийся момент, где тебе нужно быстро многократно нажимать на кнопку, продолжая раз за разом подтверждать свои намерения, что значительно усиливает эмоциональный эффект за счёт большей связи с происходящими действиями","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"What Remains of Edith Finch","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/501300/What_Remains_of_Edith_Finch/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", хоть и является симулятором ходьбы, подаёт историю не только через озвучку рассказчиком, но и через геймплей. Например, в главе про мальчика, который раскачался на качелях и улетел с обрыва, ты не просто слушаешь/смотришь эту историю - тебе самому предстоит раскачаться","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"Dragon’s Dogma 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/2054970/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" выбор стороны в конфликте принимается через непосредственно нанесение урона тем персонажам, кого ты считаешь противниками. Подобное очень сильно способствует тому, чтобы игрок еще больше ассоциировал себя с персонажем и не было этой четкой грани, что сюжет отдельно, геймплей отдельно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Тот Самый Келин сгорел с книжки для игровых сценаристов","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/CJE_BcGthUw?si=MCb6iJk92-2EweKf&t=219","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Сеттинг и сюжет - не отговорка","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#setting-and-story-is-not-an-excuse","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"c0c5a74d-8aef-49bd-b0d2-ecee90bb3c13","slug":"rationality-types","title":"3 типа рациональности","category":"classifications","content":{"type":"doc","content":[{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В игре есть одна доминирующая стратегия, которая может протащить всю игру","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В игре есть N стратегий, доминация которых чередуется по мере прохождения и определяется статичными факторами","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Доминирующая стратегия определяется в моменте, меняясь от динамических факторов","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примеры:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Меч на 1000 урона vs мечи на 100 урона при условии, что у противников нет контрмер на первый","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разные виды оружия наносят разный стихийный урон, а у противников разные стихийные резисты","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Противник чередует свои атаки в случайном порядке. Часть атак можно избежать несколькими способами. Но засчёт случайного порядка, определённые способы уворота на момент тех или иных атак могут быть недоступны, либо их сложнее исполнить","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также: ","type":"text"},{"text":"рациональный агент","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/glossary#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"b47723a6-0525-41f5-bddc-4dad2c74a02f","slug":"depth-vs-breadth","title":"Глубина vs Ширина","category":"classifications","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в ширину","type":"text","marks":[{"type":"bold"}]},{"text":" - добавление в игру нового контента, который является альтернативой, либо дополнением к уже имеющемуся","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в глубину","type":"text","marks":[{"type":"bold"}]},{"text":" - модернизация имеющегося и/или добавление нового контента, делающие игровой процесс более продуманным","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примеры:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в ширину","type":"text","marks":[{"type":"bold"}]},{"text":": добавление новых играбельных персонажей, новых локаций, новых квестов","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в глубину","type":"text","marks":[{"type":"bold"}]},{"text":": добавление выгодных интеракций между стихиями, засчёт чего игрок захочет их комбинировать; добавление шкалы остроты оружия, необходимой для блокирования и нанесения урона с возможностью её восполнения в бою, создавая тем самым менеджмент этой остроты","type":"text"}]}]}]}]}},{"id":"bcaeab60-9518-4028-b924-92eabf6324bc","slug":"service-work","title":"Служебная работа","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Совокупность рутинных или технических операций, которые не являются частью основных ","type":"text"},{"text":"челленджей","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/glossary#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" игры и не требуют от игрока существенных навыков, планирования или принятия интересных решений","type":"text"}]},{"type":"paragraph","content":[{"text":"Часто эти операции связаны с обслуживанием внутриигровых ресурсов, инвентаря, интерфейсов и т.п. и служат лишь для поддержания рабочего состояния игрового процесса, но не вносят в него нового опыта","type":"text"}]}]}},{"id":"7e936df6-5cf0-43ea-af7a-e7683acd11e7","slug":"neon-abyss-moment","title":"\"Neon Abyss\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Реализация билдостроения, при которой всё синергирует со всем и любая конфигурация персонажа эффективна. Соответственно, принятие игроком решений как таковое отсутствует, а конечные билды едва ли чем-то отличаются друг от друга","type":"text"}]},{"type":"paragraph","content":[{"text":"Названа в честь рогалика ","type":"text"},{"text":"Neon Abyss","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/788100/Neon_Abyss/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" как яркого примера подобной ситуации","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Как делать крутое билдостроение?","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/pmYTndWoWgQ","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"073dd9d2-b900-4e4f-b958-e5944e149dd2","slug":"genre-is-secondary","title":"Жанры вторичны","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Жанры вторичны по отношению к общим принципам, по которым строятся игры","type":"text"}]},{"type":"paragraph","content":[{"text":"Под общими принципами имеется в виду то, что эксплуатирует триггеры тех или иных эмоций в человеке. Например, удовольствие от видимого прогресса, азарт итд. Подобные штуки могут быть достигнуты совершенно разными способами, и для этого необязательно делать по уже известному шаблону, внося в игру в том числе и лишние элементы, ведь так делают все","type":"text"}]},{"type":"paragraph","content":[{"text":"Соответственно, нет ничего плохого и в том, чтобы предложить игре какое-либо изменение, которое \"перенесёт\" игру в другой жанр, если так в ней станет меньше противоречий и она станет лучше эксплуатировать выбранные триггеры","type":"text"}]},{"type":"paragraph","content":[{"text":"Рогалики, диаблоиды, мобы, пошаговые рпг, соулслайки - если их декомпозировать, все эти игры состоят практически из одних и тех же систем, просто в разных пропорциях и с разной углублённостью","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему контртейки \"это уже другая игра будет\" в контексте фикса тех или иных проблем не принимаются. Обсуждать нужно, хороша ли игра сама по себе как совокупность связанных между собой игровых систем, а не насколько это каноничный пошаговый рогалик","type":"text"}]},{"type":"paragraph","content":[{"text":"То же самое касается, на самом деле, и синонимов вроде \"наследия серии\" итд. Фанаты \"серии\" привыкают к тем или иным проблемам и перестают их замечать. А те, для кого проблемы критичны, отсеиваются и больше не дают свой фидбек. Ввиду чего образуется пузырь. Но если сломать этот пузырь и всё же что-то изменить, то велика вероятность, что \"серия\" на самом деле интересна куда бОльшему числу игроков, просто они обходили её стороной","type":"text"}]}]}},{"id":"dbd39421-4991-469a-b2d8-c4ce089baef5","slug":"strive-for-perfection","title":"Идеал недостижим, но к нему можно стремиться","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"\"Идеальных вещей в нашем мире не существует\"","type":"text","marks":[{"type":"italic"}]},{"text":" - это справедливое утверждение, которое, к сожалению, часто используют для того, чтобы сказать, что критики занимаются ерундой, что и так всё хорошо, что не нужно ничего улучшать или это вовсе невозможно","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот, идеальных вещей действительно не существует. Но если в продукте есть места, которые можно улучшить - это стоит сделать. Если таких мест не наблюдается, но присутствуют какие-либо противоречия в дизайне - можно порассуждать над альтернативами","type":"text"}]}]}},{"id":"c6b5c284-4932-4349-bff6-f1f56706931c","slug":"emergence","title":"Эмерджентность","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Наличие у системы свойств, не присущих её компонентам по отдельности","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры эмерджентности:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"Brotato","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1942280/Brotato/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" такие характеристики как \"высокая регенерация HP\" или \"отражение урона\" по отдельности могут присутствовать у кого угодно. Но если соединить их вместе, то появится возможность отыгрывать \"быка\" - вместо использования оружия умышленно налетать на врагов, наносить им урон обраткой и быстро восстанавливать здоровье обратно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Эмерджентность может быть ","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"как явно заданной - например, появление новых свойств у некоторых комбинаций амулетов в ","type":"text"},{"text":"Hollow Knight","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/367520/Hollow_Knight/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" вроде восстановления маны через паучков","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"так и неявно появляться из синергий - например, продление кадров неуязвимости после получения урона вкупе с ускорением лечения может дать игроку возможность лечиться в любое время","type":"text"}]}]}]}]}},{"id":"5691aee4-fb32-434d-94df-2f05b99bbb17","slug":"mechanics","title":"Механика","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Дискретный минимальный элемент игрового процесса, который определяется набором конкретных правил или параметров и выполнен таким образом, что он может быть ясно идентифицирован и изолирован в рамках более широкой системы игры","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры механик: атака; статус-эффект; дивиденды в Balatro; стресс в Darkest Dungeon","type":"text"}]}]}},{"id":"e9795f04-dd38-4e87-b8aa-fea0afdb7f6a","slug":"qol-should-not-have-opportunity-cost","title":"QoL не должен стоить геймплейных возможностей","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Игрок не должен выбирать между тем, видеть себя на карте ","type":"text"},{"text":"(в игре, где вокруг этого знания не выстроен какой-то геймплей)","type":"text","marks":[{"type":"italic"}]},{"text":" или иметь больше урона. Даже если это выбор между \"иммерсивным\" и обычным прохождением игры. Даже если этому придумано какое-то нарративное обоснование","type":"text"}]},{"type":"paragraph","content":[{"text":"Это может быть опцией, но включение ","type":"text"},{"text":"QoL","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"quality-of-life","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" не должно требовать от игрока отказа от геймплейных возможностей","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Сеттинг и сюжет - не отговорка","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#setting-and-story-is-not-an-excuse","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"8a186983-09e9-404a-90d4-b3fe690e25df","slug":"fun-should-be-rewarded","title":"\"Весёлый\" геймплей должен вознаграждаться","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Если в игре нерационально пользоваться арсеналом инструментов или производить какие-то сложные действия, а рациональный геймплей сводится к скучному спаму двух кнопок - это проблема игры, поскольку в таком случае у нас 3 варианта исходов:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок, который проактивно играет \"весело\" безотносительно выгоды, получит удовольствие и так, и так","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок, который плывёт по течению и играет рационально, получит скучный игровой опыт","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок, который хочет играть весело, но видит, что игра за это не вознаграждает, расстроится","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"И если это пофиксить, то для первого ничего не изменится, а остальным станет лучше","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Адвокат Supergiant Russia критикует мой обзор Hades","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/WBTeef9tI3M","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"2232dae7-6ee9-47af-b8f3-cad9f15b1866","slug":"quality-of-life","title":"Quality of Life (QoL)","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Геймдизайнерские и технические решения, сделанные для удобства игрока и/или упрощения ","type":"text"},{"text":"служебной работы","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/glossary#service-work","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Примеры:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Кнопка \"Отсортировать предметы\" в инвентаре RPG-игры","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ускорение анимаций в ","type":"text"},{"text":"Slay the Spire","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/646570/Slay_the_Spire/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"a56b7fed-0259-4770-98bd-c735f4c95993","slug":"synergy","title":"Синергия","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Воздействие двух элементов друг на друга таким образом, что их объединённый эффект превышает сумму эффектов по отдельности","type":"text"}]},{"type":"paragraph","content":[{"text":"Например","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Удвоенная скорость атаки и удвоенный урон вместе дают четырёхкратный прирост DPS. Тогда как по отдельности выходит трёхкратный (100+100+100)","type":"text"}]}]}]}]}},{"id":"3e34c301-e2df-4741-9bc6-2ebb219ee2f5","slug":"cargo-cult","title":"Карго-культ","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Общее понятие, не связанное непосредственно с геймдизайном, означающее поверхностную имитацию чего-либо без глубинного понимания причинно-следственных связей в надежде получить схожие с объектом копирования результаты","type":"text"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"text":"Отсылает термин к событиям второй мировой войны, когда на островах Меланезии размещались военные базы и аэропорты, через которые доставляли оружие, припасы, одежду и другие грузы. Часть этих вещей доставалась коренным жителям этих островов, как проводникам","type":"text"}]},{"type":"paragraph","content":[{"text":"Многие из них тогда видели все это впервые. И будучи неспособными объяснить происхождение этих грузов (cargo), кроме как проявлением чуда, стали верить в волшебную силу техники и других объектов","type":"text"}]},{"type":"paragraph","content":[{"text":"Когда закончилась война и поток грузов прекратился, местные жители решили, что, копируя манеры и постройки \"чужаков\", смогут расположить к себе духов, — и стали имитировать поведение военных: размечали взлетно-посадочные полосы, строили самолеты из пальм и соломы, делали наушники из кокосов, ружья из пало��, ходили строем и рисовали на себе ордена и надписи USA. Делали это в надежде снова получить \"небесные дары\"","type":"text"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"text":"В контексте игр карго-культом можно назвать ситуации, когда какие-то механики или другие аспекты заимствуют у других проектов, без понимания причин актуальности этих элементов в рамках контекста игры","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, перенос механики потери душ при смерти из солсов в абсолютно линейную игру. Потерянные души дополнительно мотивируют игрока после смерти пойти именно туда, где он только что умер, и в рамках нелинейных солсов эта дополнительная мотивация смысл имеет. В рамках же линейной игры у игрока в любом случае только один вариант, куда ему двигаться, из-за чего дополнительные бонусы к выбору, куда пойти, просто бессмысленны","type":"text"}]}]}},{"id":"5a8ca4eb-d92e-46c8-b889-e15c6c9d4dc2","slug":"transformer-and-diffusion","title":"Подходы к разработке: Transformer и Diffusion","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Это аналогия на два популярных вида нейросетей:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Transformer. Они работают по принципу последовательного предсказывания следующего токена после серии предыдущих. Так работают ChatGPT и другие языковые модели. То есть они последовательно слово за словом генерируют ответ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Diffusion. Такие модели работают иначе: они начинают с шума и постепенно проявляют конечный результат. По такому принципу работают генераторы картинок, проявляя из шума эти самые картинки","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"По аналогии с этим можно подходить и к разработке (например игр): ","type":"text"}]},{"type":"paragraph","content":[{"text":"Можно, как Transformer'ы делать все последовательно от начала и до конца без перескакиваний и переделок. То есть сначала всё на этапе диздока продумал, потом пошел это последовательно кодить, потом приделывать картинки от дизайнера и т.д.","type":"text"}]},{"type":"paragraph","content":[{"text":"Такой подход спасает от постоянных переделок, но оставляет риск достаточно поздно заметить фундаментальные проблемы, возникшие еще на этапе идеи, которые будут всё руинить и сильно ограничивать","type":"text"}]},{"type":"paragraph","content":[{"text":"Можно, как Diffusion'ы разрабатывать множество разных элементов и аспектов игры параллельно, постепенно \"проявляя их из шума\"","type":"text"}]},{"type":"paragraph","content":[{"text":"В таком подходе проще рано заметить какие-то фундаментальные проблемы и проще их исправить. Но самих переделок потенциально значительно больше. Также есть проблема с тем, что конечный результат даже части игры не доступен и его соответсвенно невозможно показать, пока ты не дошел до конца. Комфорт применения данного подхода в том числе сильно зависит от уровня компетенций, потому что, как минимум с позиции написания кода, понимание принципов построения более легко скейлящегося (расширяющегося) кода сильно облегчает процесс","type":"text"}]},{"type":"paragraph","content":[{"text":"Оба подхода возможны, оба подхода имеют свои компромиссы, ни один не доминирует над другим сам по себе","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Подкаст о геймдизайне с Kelin2025","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/NwnN5wZnE28?si=3arPOWhDq5-f9QU9&t=2022","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"790b77e0-8001-453b-9457-e05306acd380","slug":"functional-and-aesthetic-aspects","title":"Геймплейно-функциональный и эстетико-нарративный аспекты игр","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Все содержимое игры глобально можно поделить на два аспекта:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Геймплейно-функциональный — правила, механики, хитбоксы, системы, их взаимосвязи, игровой баланс, смысловая часть интерфейса, сам факт наличия каких-то звуковых или визуальных маркеров и другие вещи, определяющие логику игры и логику поведения игрока","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Эстетико-нарративный — весь визуал, анимации, стилистика, оформление, сеттинг, внешний вид того же интерфейса и визуальных маркеров, все звуковое оформление игры, качество текста и другие вещи, касающиеся именно того, как игра звучит, выглядит и обеспечивает повествование","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Такое разделение в том числе позволяет легко определять, где у нас действительно разные геймплейно механики, а где нет. Например эффекты отравления и горения во многих играх геймплейно представляют из себя один и тот же DOT (Damage Over Time), но эстетико-нарративно отличаются. То же относится и к разным вариантам нюков (nuke — способность наносящая разовый урон) из первых двух Mass Effect","type":"text"}]}]}},{"id":"3ae1605f-1ec0-4b98-a84c-ed31b8ee807c","slug":"challenging-difficulty","title":"Связь сложности и челленджовости","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Порог ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", после которой игрок с большой вероятностью начнёт жаловаться на духоту, ограничен её ","type":"text"},{"text":"челленджовостью","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"С момента, как повышение сложности перестаёт переводить ","type":"text"},{"text":"потенциальную челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#potential-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в ","type":"text"},{"text":"реализованную","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", перестаёт появляться новый игровой опыт и остаётся лишь механическая дрочь, с которой будет плеваться значительная доля аудитории, а оценят лишь те, кому игра невероятно заходит","type":"text"}]},{"type":"paragraph","content":[{"text":"В свою очередь, чрезмерное понижение ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" может перевести бОльшую часть ","type":"text"},{"text":"реализованной челленджовости","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в ","type":"text"},{"text":"потенциальную","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#potential-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" и превратить предполагаемые к постоянному использованию ","type":"text"},{"text":"механики","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в ","type":"text"},{"text":"опциональные","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"5eda4951-1c9e-4c54-aa82-a75cb0475911","slug":"wanna-have-fun-moment","title":"\"Хочу играть весело\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Явление, когда игрок играет нерационально в угоду фана","type":"text"}]},{"type":"paragraph","content":[{"text":"Это может быть как сознательным решением ","type":"text"},{"text":"(например, умышленно не использовать предметы)","type":"text","marks":[{"type":"italic"}]},{"text":", так и неосознанным ","type":"text"},{"text":"(игрок в пылу экшна активно спамит всеми кнопками, не замечая, что это на самом деле либо избыточно, либо вовсе бесполезно)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Стоит понимать, что с точки зрения анализа гейм-дизайна и то, и то - девиация. Если взглянуть на примеры выше:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Сознательное, скорее всего, единичный случай, который не имеет особо смысла разбирать","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"А под неосознанное нужно адаптировать гейм-дизайн так, чтобы это было оптимально. Чтобы и рациональный игрок не свалился в одну кнопку и не начал скучать","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"Весёлый\" геймплей должен вознаграждаться","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#fun-should-be-rewarded","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Адвокат Supergiant Russia критикует мой обзор Hades","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/WBTeef9tI3M","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"071773b6-87d6-49d0-baa3-baec720ede78","slug":"neko-mario-moment","title":"\"Neko Mario\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Neko Mario","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.nekomario.com/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" ","type":"text"},{"text":"(или Cat Mario)","type":"text","marks":[{"type":"italic"}]},{"text":" - фанатская версия Mario, в которой на каждом шагу встречаются крысиные ловушки, избежать которые можно, лишь предварительно о них зная","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, перед ямой, через которую нужно перепрыгнуть, будет невидимый низкий потолок. Или может провалиться пол, причём таким образом, что если на него наступить, то падения не избежать","type":"text"}]},{"type":"paragraph","content":[{"text":"\"Neko Mario\" moment","type":"text","marks":[{"type":"bold"}]},{"text":" обычно используется, когда подобный троп встречается в игре, которая не позиционирует себя как игра на потроллить","type":"text"}]},{"type":"paragraph","content":[{"text":"Запуская ","type":"text"},{"text":"Neko Mario","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.nekomario.com/syobon.html","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", игрок заранее готов к тому, что здесь его будут всячески разводить. И ему будет интересно, как его разведут на этот раз. Если же такое внезапно встречается в обычной игре, фидбеком зачастую будет \"ну и зачем это было?\"","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Дизайн должен быть последовательным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#design-should-be-consistent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"6aac0e26-c34f-4e51-b105-4c2b043714f5","slug":"design-should-be-consistent","title":"Дизайн должен быть последовательным","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Логика работы ","type":"text"},{"text":"механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" и баланс ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" должны быть реализованы таким образом, чтобы синергировать друг с другом и работать на какую-то идею, а не противоречить друг другу","type":"text"}]},{"type":"paragraph","content":[{"text":"Распространённой ошибкой в гейм-дизайне является расхождение в ответах на вопросы ","type":"text"},{"text":"\"что мы хотим от игрока\"","type":"text","marks":[{"type":"italic"}]},{"text":" и ","type":"text"},{"text":"\"за что мы хотим его наказывать\"","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"К примеру, мы берём за основу предположение ","type":"text"},{"text":"\"агрессивный геймплей - это круто\"","type":"text","marks":[{"type":"italic"}]},{"text":". Соответственно, мы даём игроку большой набор агрессивных инструментов, даём им какие-то сочные анимации и звуки, доставляющие удовольствие при каждом их прожатии. Но затем сильно наказываем за каждое проявление агрессии, потому что игрок якобы слишком силён. В результате игрок будет играть пассивно - от защиты, выжидания итд. Поскольку мы дизайнили игру, предполагая агрессивный геймплей, пассивный выходит неинтересным","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот - если в такой игре мы хотим добиться ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в значении X, но сохранить геймплей интересным, то куда разумнее не добавлять противнику штуки вроде контактного урона, спонтанных парирований итд, а добиться этого другими решениями. Даже банальное увеличение здоровье врагу на такое значение, чтобы ","type":"text"},{"text":"сложность","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" добралась до X засчёт остальных ошибок, будет веселее. Ведь так игрок всё ещё потратит на босса X попыток, но будет играть через задуманный \"интересный\" стиль","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"Happy hob\" moment","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#happy-hob-moment","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"ad10f6c5-60b0-4f40-a7c4-029437274bea","slug":"expanding-satisfaction","title":"Расширение диапазона довольных игроков","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Любой разработчик заинтересован в том, чтобы его игра смогла охватить и удовлетворить как можно более широкий пласт игроков среди потенциальной целевой аудитории игры. Не только с точки зрения повышения доходов и известности, но и в том числе творческой самореализации","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему там, где есть возможность расширить диапазон довольных игроков ","type":"text"},{"text":"без ущерба текущей аудитории","type":"text","marks":[{"type":"bold"}]},{"text":", это стоит сделать","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 1. Assist-режимы и варианты сложности","type":"text"}]},{"type":"paragraph","content":[{"text":"Есть множество игр, геймплей которых раскрывается именно на высокой сложности (см. ","type":"text"},{"text":"связь сложности и челленджовости","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenging-difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":")","type":"text"}]},{"type":"paragraph","content":[{"text":"Такие игры, однако, могут иметь и составляющие, которые представляют интерес безотносительно сложности","type":"text"}]},{"type":"paragraph","content":[{"text":"Также есть люди, которые могли бы проникнуться игрой, но без нормальной кривой обучения не успеют набрать критическую массу заинтересованности, чтобы решить, что оно стоит того","type":"text"}]},{"type":"paragraph","content":[{"text":"В таких случаях имеет смысл рассмотреть такие решения как: варианты/кастомизация сложности, ассист-режимы ","type":"text"},{"text":"(таргетное упрощение/отключение определённых механик)","type":"text","marks":[{"type":"italic"}]},{"text":", сюжетный режим ","type":"text"},{"text":"(на случай, если в игре есть стоящий внимания сюжет)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Примеры из игр","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"SIFU","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2138710/Sifu/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" есть механика старения - после смерти персонаж возрождается, но стареет, а по достижению определённого возраста ты не можешь продолжать. По сути это один большой HP-бар на всю игру, вынуждающий идеально пройти предыдущие миссии перед заходом на следующие. Несмотря на то, что как маркетинговый гиммик эта механика привлекла внимание, дальше второго босса ушло лишь 30% игроков. Тем временем, последнего босса в ","type":"text"},{"text":"Streets of Rage 4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/985890/Streets_of_Rage_4/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" прошло 35%. Ачивки, подразумевающие повторное прохождение, также имеют довольно высокий %. Таким образом, полноценным прохождением ","type":"text"},{"text":"SoR4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/985890/Streets_of_Rage_4/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" насладился бОльший процент игроков, а ценителей хардкора игра не оттолкнула. Впоследствии в ","type":"text"},{"text":"SIFU","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2138710/Sifu/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" добавили вариант сложности с отключённой механикой старения","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Источники статистики: ","type":"text"},{"text":"SIFU","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.trueachievements.com/game/Sifu/achievements","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", ","type":"text"},{"text":"Streets of Rage 4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.trueachievements.com/game/Streets-of-Rage-4/achievements","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nine Sols","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1809540/Nine_Sols/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - метроидвания с довольно сложной боёвкой и боссами. В ней так же есть сюжетный режим. Так, ценители боёвки пойдут в обычный режим, и их опыт никак не изменится; а более казуальная аудитория всё ещё насладится историей без душки от сложных боссфайтов","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Celeste","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/504230/Celeste/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - precision-платформер, в котором есть как плавный порог вхождения, так и assist-режим, упрощающий и даже отключающий некоторые механики. Игра имеет отличные продажи, 97% положительных отзывов, а также даже спустя 7 лет после релиза находится в первой строчке популярных игр на ","type":"text"},{"text":"speedrun.com","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.speedrun.com/games","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" и огромное количество хардкорных модов","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 2. Реактивные vs проактивные игроки","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Реактивные игроки склонны использовать только рациональные механики, игнорируя остальные. Если в игре слишком много ","type":"text"},{"text":"опциональных механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" и/или именно они являются наиболее интересными и увлекательными по сравнению с рациональными, то это ухудшит игровой опыт для данной категории игроков. Потому что их геймплей будет склоняться к чему-то скучному, но практичному","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Проактивные игроки не против использовать и ","type":"text"},{"text":"опциональные механики","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", если те покажутся им весёлыми. Их игровой опыт будет одинаково удовлетворительным при любом соотношении механик","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Таким образом, у реактивных игроков есть потребность в том, чтобы в игре было как можно больше качественных рациональных механик. Тогда как у проактивных игроков противоположной потребности в нерациональных механиках нет - для них этот момент безразличен","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему повышение рациональности механик игры до достаточного уровня сделает реактивных игроков довольными, никак при этом не навредив проактивным","type":"text"}]}]}},{"id":"a5aab868-d651-4ab3-bedb-aa74ec833c6f","slug":"dont-hide-what-is-already-known","title":"Не скрывай информацию, если она уже известна","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Многие игры скрывают от игрока часть информации, и это может иметь свою пользу. Например, чтобы не нагружать игрока лишней информацией в начале игры, можно не показывать игроку некоторые вкладки интерфейса до тех пор, пока они не понадобятся","type":"text"}]},{"type":"paragraph","content":[{"text":"В то же время, если игрок в процессе игры узнает какую-то информацию, то нет смысла её продолжать скрывать - польза ","type":"text"},{"text":"(как с точки зрения геймплея, так и с точки зрения порога вхождения)","type":"text","marks":[{"type":"italic"}]},{"text":" исчезает, и дальнейшее сокрытие переходит в разряд проблемы ","type":"text"},{"text":"QoL","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#quality-of-life","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Примеры","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"The Binding of Isaac","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/113200/The_Binding_of_Isaac/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" долгое время отсутствовало описание предметов. В первый раз это, хоть и вредит принятию решений, но имеет и пользу - чтобы игрок тыкнулся в новый предмет и получил какой-то вау-эффект, какую-то новую игровую ситуацию. Во второй раз из этого сокрытия информации не следует ничего, кроме того, что игрок должен держать в голове каждый из тысячи увиденных предметов, в одной из сотен игр, в которые он играет, в жизни, полной информации","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"Hollow Knight","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/367520/Hollow_Knight/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" карта каждой локации становится видна только после её покупки, даже если у игрока есть перо (предмет, рисующий карту) и он уже пробежал всю локацию. Опять же, при первом прохождении локации это имеет смысл - мы создаём неизвестность и хотим, чтобы игрок потыкал каждый уголок сам; чтобы пошёл, куда захочет, а не ровно туда, где лежат самые ценные секреты/основной сюжет/итд. Во второй же заход нам уже нечего оберегать - это лишь породит путаницу \"а где была вот эта хрень\" и потратит лишнее время на плутание по локации, в которой не происходит ничего нового","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В The Binding of Isaac добавили описание предметов","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/news/app/250900/view/521976260528701584","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"19147101-3ef2-4ae4-a215-3545c6aba6a0","slug":"happy-hob-moment","title":"\"Happy hob\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Ситуация, при которой игрок, вместо ведения активного боя, играет максимально пассивно и безопасно, порой доходя до того, что удар наносится строго в одно максимально стабильное окно","type":"text"}]},{"type":"paragraph","content":[{"text":"Названа в честь одноимённого no-hit раннера ","type":"text"},{"text":"The Happy Hob","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/channel/UC0E1n0GRgBW5gR7y7H9TjZQ","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]},{"type":"paragraph","content":[{"text":"Эта ситуация свойственна плохо задизайненным боевым системам, в которых игроку дают какой-то арсенал инструментов, но баланс угрозы и выгоды от их использования хуже, чем при стиле игры happy hob","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Дизайн должен быть последовательным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#design-should-be-consistent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"643adf79-baf9-40df-ab05-905460a66f44","slug":"marketing-promise","title":"Маркетинговое обещание","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Вся публично доступная информация со стороны разработчика, формирующая у игрока ожидания того или иного игрового опыта","type":"text"}]},{"type":"paragraph","content":[{"text":"К маркетинговому обещанию можно отнести:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Трейлеры","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Описание игры на странице в магазине","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Эстетико-нарративные элементы, подразумевающие определённый геймплей ","type":"text"},{"text":"(например, персонаж, выглядящий как варвар, создаёт ожидание битвы \"напролом\")","type":"text","marks":[{"type":"italic"}]}]}]}]},{"type":"paragraph","content":[{"text":"Расхождение итогового игрового опыта с ожиданием является либо провалом маркетинга ","type":"text"},{"text":"(рекламировали шутер, а игра - стелс-хоррор)","type":"text","marks":[{"type":"italic"}]},{"text":", либо неудачными решениями в гейм-дизайне ","type":"text"},{"text":"(варвар оказался ваншотным)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Отличие маркетиногового обещания от задумки автора в том, что маркетинговое обещание игроку демонстрируют публично и разночтения исключены. Тогда как апелляция к задумке автора зачастую являются лишь спекуляцией в попытках объяснить, почему геймплей вышел таким, какой он есть","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Автор - мёртв","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#author-is-dead","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"55ad0f3c-9e1a-463b-80ee-8fac439025e3","slug":"a-purpose-of-a-system-is-what-it-does","title":"Суть системы в том, что она делает","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Иногда люди ","type":"text"},{"text":"(как разработчики, имеющие какую-то задумку, так и игроки понравившихся продуктов)","type":"text","marks":[{"type":"italic"}]},{"text":" при обсуждении какой-то неинтуитивной или нерабочей системы начинают объяснять, в чём её \"суть\" - как она работает, что игрок пропустил и так далее","type":"text"}]},{"type":"paragraph","content":[{"text":"На самом деле, касается не только обсуждения. Часто у гейм-дизайнера может замылиться глаз - например, он во время тестов будет прокачивать персонажа в рогалике, а потом выяснится, что игра абсолютно спокойно проходится с полным игнором прокачки ","type":"text"},{"text":"(тру стори из девлога, кстати)","type":"text","marks":[{"type":"italic"}]},{"text":". И они могут даже реализовать в игре подробный туториал о том, как делать такую-то штуку, а по итогу окажется, что штука нахрен не нужна","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нет смысла напоминать, что суть системы в X, если она проваливает X. Если игрок не увидел важную дверь в тёмном дальнем углу - наверное, нужно её куда-то передвинуть или выделить","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нет смысла объяснять, как красиво можно комбинировать приёмы и протезы в условной Sekiro, если игрок всё это скипнул из-за расходного ресурса и сомнительной полезности","type":"text"}]}]}]}]}},{"id":"48a7dc93-23ca-424a-a5eb-46a74dc36c28","slug":"player-goals","title":"Про целеполагание игрока","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Анализ строится от препозиции, что цель игрока при запуске ","type":"text"},{"text":"игры","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#game","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" - получить от неё удовольствие","type":"text"}]},{"type":"paragraph","content":[{"text":"Следствия и примечания","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Первые часы в игре крайне важны, чтобы завлечь игрока. Иначе он просто уйдёт ","type":"text"},{"text":"\"получать удовольствие\"","type":"text","marks":[{"type":"italic"}]},{"text":" в другую игру","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В целях получения удовольствия, игрок может давать игре небольшие уступки. Например, умышленно игнорировать совсем чизовые стратегии, аннулирующие игровые ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". Или закрывать глаза на объективную слабость субъективно понравившихся ","type":"text"},{"text":"механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". Однако, чем больше общий объём таких уступок, тем меньшее удовлетворение игрок в конечном счёте получит. Поскольку игроку вместо получения интересного игрового опыта \"из коробки\" придётся додумывать гейм-дизайн за разработчика, при этом осознавая, что все его сверхусилия на самом деле не необходимы и не поощряются игрой","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"См. ","type":"text"},{"text":"Весёлый геймплей должен быть рациональным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#fun-should-be-rewarded","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Для игр/разработчиков с высокой репутацией и популярностью игроки, как правило, дают гораздо больше уступок. В таких случаях не стоит принимать ярко положительный отзыв как сигнал о том, что с гейм-дизайном в игре всё отлично. Зачастую людям нравятся такие игры не \"благодаря\", а \"вопреки\" определённым решениям. И как бы такие люди ни заявляли обратного, другие игры, которые повторяют проблемные решения, оказываются либо завалены негативными отзывами, либо в принципе остаются незамеченными","type":"text"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Тотальное оказуаливание и/или удаление каких-либо плохо задизайненных сложных игровых сегментов не является решением для удовлетворения игрока. Поскольку мы в таком случае удаляем геймплей и удовольствие не от чего получать. Посему любое предложение в духе ","type":"text"},{"text":"\"удалить из игры контактный урон\"","type":"text","marks":[{"type":"italic"}]},{"text":" подразумевает не только удаление оного, но и доработку остальных игровых систем таким образом, чтобы избавиться от проблемных решений, но всё ещё предоставить текущему игроку сопоставимый по сложности контент","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Такие цели как ","type":"text"},{"text":"\"пройти игру без урона\"","type":"text","marks":[{"type":"italic"}]},{"text":", ","type":"text"},{"text":"\"пробежать её как можно быстрее\"","type":"text","marks":[{"type":"italic"}]},{"text":", ","type":"text"},{"text":"\"научиться проходить игру красиво\"","type":"text","marks":[{"type":"italic"}]},{"text":" и прочие ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" не рассматриваются, если игра сама не предполагает такой цели и не вознаграждает за это","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Может показаться, что этот принцип расходится с ","type":"text"},{"text":"рациональным агентом","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". На самом деле это не так. Связь рационального агента и данного принципа стоит расценивать следующим образом: игрок будет действовать рационально в большинстве случаев, но иногда может отсечь некоторые опции, если те уничтожают геймплей. При этом, в рамках оставшихся опций геймплей всё ещё будет стремиться к рациональному. И даже в таких случаях большинство игроков скорее всего всё ещё будут играть рациональными опциями, ничего не отсекая ","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Например, несмотря на то, что знак Странницы и заклинание \"Буйство Нитей\" в Silksong являются самыми рациональными И самыми геймплейно примитивными опциями, они всё равно были топ 1 выбором игроков с огромным отрывом. См. статистика ","type":"text"},{"text":"по знакам","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://t.me/kelin2play/1361","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" и ","type":"text"},{"text":"заклинаниям","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://t.me/kelin2play/1413","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}]}]}},{"id":"fc90d17f-b545-426d-9522-b6b7f9f6e173","slug":"ideal-game","title":"Идеальная игра","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Игра","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#game","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", которую нельзя сделать лучше","type":"text"}]},{"type":"paragraph","content":[{"text":"Выражается в виде","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Отсутствия противоречий между элементами, упущений в презентации системы и прочих ошибок","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Исчерпания возможностей добавить новый элемент, не породив противоречий","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Исчерпания возможностей провести синергию между существующими элементами системы","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Диапазон довольных игроков","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#expanding-satisfaction","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" невозможно расширить без вреда уже существующей аудитории","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примечания","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Два синергирующих друг с другом процесса будут однозначно лучше двух несвязанных ","type":"text"},{"text":"(см. ","type":"text","marks":[{"type":"italic"}]},{"text":"Онтологический принцип холизма","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://ru.wikipedia.org/wiki/%D0%A5%D0%BE%D0%BB%D0%B8%D0%B7%D0%BC","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}},{"type":"italic"}]},{"text":")","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Возможности для добавления новых элементов и проведения синергий достаточно широки. Однако, они не приведут к реализации всего в одной игре. Каждое последующее добавление нового элемента отсекает другие, которые противоречат ему. Таким образом, из бесконечного множества любых возможных механик вырисовывается конечное множество, которое не может быть далее расширено","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Например, добавление гоночных автомобилей в ","type":"text"},{"text":"Elden Ring","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/1245620/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" не сделает игру лучше. Поскольку, в таком случае, текущие игроки получат совершенно левый для них контент, который, к тому же, будет мешать/отвлекать от взаимодействия остальным","type":"text"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"Безыдейные, стерильные, ведущие во всём за ручку\"","type":"text","marks":[{"type":"italic"}]},{"text":" и прочие отсылающие к играм Ubisoft эпитеты не относятся к идеальным играм по четвёртому критерию","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Платформер, в котором нет никаких противоречий, есть внятный туториал, он максимально богат механически, синергии исчерпаны, но все действия в нём нужно совершать с невозможной для человека скоростью/реакцией ","type":"text"},{"text":"(т.е. он де факто непроходим)","type":"text","marks":[{"type":"italic"}]},{"text":", не является идеальной игрой, поскольку диапазон довольных игроков в таком случае равен нулю, а невозможные тайминги противоречат задаче в них попадать","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примеры игр, близких к идеалу: Portal 2, Into the Breach, Devil Daggers, Spelunky, Baba is You","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Идеал недостижим, но к нему можно стремиться","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#strive-for-perfection","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"4a1572c1-5001-48df-b1f1-2f9541867e6f","slug":"setting-and-story-is-not-an-excuse","title":"Нарратив не должен жертвовать геймплеем","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Практически любую идею можно обыграть так, чтобы было и \"прикольно\" с точки зрения \"обыграть сеттинг/нарратив\", и чтобы не мешало игроку","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, в ","type":"text"},{"text":"Hollow Knight: Silksong","type":"text","marks":[{"type":"bold"}]},{"text":" есть суп, повышающий скорость атаки. Но восполняются запасы только в конкретном месте ","type":"text"},{"text":"(где сидит группа блох)","type":"text","marks":[{"type":"italic"}]},{"text":". С точки зрения нарратива это обосновано - мол, блохи варят суп, вот ты к ним приходишь за добавкой. Но с точки зрения геймплея это означает, что на закрепном боссе ты будешь вынужден периодически уходить, чтобы пополнить запасы. При этом, с точки зрения нарратива ничто не мешало разработчику обыграть это иначе - мол, ты спас наших блох, в награду с тобой пойдёт одна из них, и пусть она варит этот суп на скамейке-чекпоинте. Нарративно всё ещё \"прикольно\", но геймплейно в разы менее душно","type":"text"}]},{"type":"paragraph","content":[{"text":"Над нарративом и над геймплеем работает команда. И они согласовывают все составляющие игры. Поэтому, если какое-то решение является проблематичным с точки зрения гейм-дизайна, нарратив не является тому оправданием - его можно и подкорректировать, чтобы получить в целом менее противоречивый продукт","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игры - про геймплей","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#games-are-about-gameplay","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"6d84d23a-4d37-43c6-a4f2-31ffed3943fe","slug":"player-expression-vs-enemy-expression","title":"Player expression vs enemy expression","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Две характеристики боевых систем, определяющие степень комплексности и разнообразия на стороне игрока и на стороне противников соответственно","type":"text"}]},{"type":"paragraph","content":[{"text":"Простым словами - насколько игра даёт разгуляться игроку/противникам в плане действий, их комбинаций итд.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Высокий player expression: ","type":"text"},{"text":"Devil May Cry","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/601150/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", ","type":"text"},{"text":"ULTRAKILL","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1229490/ULTRAKILL/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Высокий enemy expression: ","type":"text"},{"text":"Elden Ring","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/1245620/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Высокий player+enemy expression: ","type":"text"},{"text":"Nioh","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/485510/Nioh_Complete_Edition/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Примечания","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Обе характеристики могут варьироваться в пределах одной игры ","type":"text"},{"text":"(например, мобы - простые болванчики, а боссы с комплексным поведением)","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"От этих характеристик напрямую зависит ","type":"text"},{"text":"челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" игры","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Максимизируя обе характеристики сразу, можно создать продукт с высоким потолком мастеринга, но с большой вероятностью высоким окажется и порог входа","type":"text"}]}]}]}]}},{"id":"c456fb63-5bd8-4a44-ac56-4d2df6166410","slug":"intent-over-inputs","title":"Намерения игрока важнее инпутов","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Игры, которые воспринимаются игроками как \"честные\", на самом деле делают огромное количество незаметных поблажек в их пользу","type":"text"}]},{"type":"paragraph","content":[{"text":"Делается это не для того, чтобы игры оказуалить. А для того, чтобы когнитивные ресурсы игрока были свободны для более комплексных и интересных задач, а более тривиальные не руинили задуманный игроком план их решения","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример: Input buffering","type":"text"}]},{"type":"paragraph","content":[{"text":"Предположим, есть некий экшн-рогалик с довольно активной боёвкой, и у игрока есть некая заряжаемая атака из лука. У этой атаки есть небольшой интервал отката ","type":"text"},{"text":"(в районе 100мс)","type":"text","marks":[{"type":"italic"}]},{"text":", чтобы стрельба шла с определённой периодичностью, а не одна стрела за другой","type":"text"}]},{"type":"paragraph","content":[{"text":"В такой игре игрок будет погружён в сражения с врагами. И он не будет думать о том, чтобы нажимать кнопку строго после завершения времени отката. Он будет думать о том, что ","type":"text"},{"text":"сейчас он выстрелит вот в этого врага, а потом вот в того, а потом побежит туда-то","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"И если не добавить буффер, который при зажатии кнопки во время отката запоминал бы это нажатие и при откате засчитывал использование атаки, то у игрока просто периодически не будет срабатывать выстрел, и это в конечном счёте его задушит. Причём, вполне вероятно, что игрок даже не поймёт, в чём было дело - подумает, что в игре инпуты кривые и не засчитываются, и оставит отрицательный отзыв","type":"text"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"text":"К таким поблажкам можно отнести","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Время койота, jump buffer'ы и аналогичные решения, сглаживающие неидеально прожатые кнопки","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Добивание противника в случаях, когда атака оставила ему 1 HP","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"итд.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Почему Celeste - один из лучших платформеров последних лет","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/watch?v=ilJ3vHSaJtg","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разбор косяков платформинга в Blasphemous","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/watch?v=0KPhhWB1z14","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Момент с AMA xkoster об этом же","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/_ZiTfc_urXQ?t=7528","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"a954e6f3-44bf-4c1c-9eba-8e7db846a2ad","slug":"rules-should-serve-a-purpose","title":"Правила подбираются под цели","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"То, какой вариант реализации механик, систем, ограничений и поощрений лучше подойдёт для игры в целом зависит от того, какой целевой игровой опыт мы хотим смоделировать","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 1: Высокий vs низкий ТТК в шутере","type":"text"}]},{"type":"paragraph","content":[{"text":"Если цель - ","type":"text"},{"text":"\"для убийства противника нужно совершать какие-то комбинации действий вместе с командой\"","type":"text","marks":[{"type":"italic"}]},{"text":", то, скорее всего, лучше подойдёт высокий","type":"text"}]},{"type":"paragraph","content":[{"text":"Если цель - ","type":"text"},{"text":"\"сделать тактическое позиционирование важным\"","type":"text","marks":[{"type":"italic"}]},{"text":", то, наверное, низкий","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 2: Наличие vs отсутствие контактного урона","type":"text"}]},{"type":"paragraph","content":[{"text":"Если мы хотим от игрока, чтобы он концентрировал внимание на перемещении врага и старался держать дистанцию, то наличие контактного урона сыграет на руку","type":"text"}]},{"type":"paragraph","content":[{"text":"Если мы хотим, чтобы игрок не боялся приближаться к врагу и не тратил слишком много внимания на перемещение противника, то лучше будет не добавлять контактный урон","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Полезность механики зависит от контекста","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics-in-vacuum","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Дизайн должен быть последовательным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#design-should-be-consistent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"039e55ed-8524-4fa0-b157-95141d8ab430","slug":"author-is-dead","title":"Автор - мёртв","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Конечный вид игры и её восприятие игроками важнее любых оправданий о замысле разработчика или причинах, по которым он сделал X так, а не иначе. Это не говоря уж о том, что за ","type":"text"},{"text":"\"задумкой автора\"","type":"text","marks":[{"type":"italic"}]},{"text":" нередко скрываются спекуляции - додумки, для чего автор сделал X","type":"text"}]},{"type":"paragraph","content":[{"text":"Есть, однако, исключение под названием ","type":"text"},{"text":"\"","type":"text","marks":[{"type":"italic"}]},{"text":"маркетинговое обещание","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#marketing-promise","class":"text-blue-500 hover:text-blue-700 underline","target":""}},{"type":"italic"}]},{"text":"\"","type":"text","marks":[{"type":"italic"}]},{"text":". Если игру всем видом продают как мясной шутер, а на самом деле в неё нужно играть как в стелс иммерсив сим, прибегая к стрельбе лишь в крайних случаях - в таком случае, будет неудивительно, если аудитория мясных шутеров будет пытаться играть в это как в мясной шутер и скажет, что это хреновый мясной шутер. Это уже не проблема гейм-дизайна, это проблема маркетинга","type":"text"}]}]}},{"id":"312d4ff3-2b75-4420-ac80-ce9a5760135f","slug":"input-vs-output-random","title":"Input vs Output Random","category":"classifications","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Input random","type":"text","marks":[{"type":"bold"}]},{"text":" - случайность, которая влияет на начальные условия или доступные опции ","type":"text"},{"text":"(например, выпадение предметов, генерация уровня)","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Output random","type":"text","marks":[{"type":"bold"}]},{"text":" - случайность, которая влияет на результат уже принятого решения ","type":"text"},{"text":"(например, шанс попадания или крита)","type":"text","marks":[{"type":"italic"}]}]}]}]}]}}];
  const customData = [{"id":"0885d017-0781-4f0b-9f0a-5fe3f4146c2d","slug":"optional-mechanics","title":"Опциональная механика","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Механика","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", которую в рамках рассматриваемой цели можно исключить и всё ещё выполнить цель","type":"text"}]},{"type":"paragraph","content":[{"text":"Можно ли её исключить или нет, определяется через ","type":"text"},{"text":"рационального агента","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"c42ca45f-d2a9-4c7a-a70a-1128884058c2","slug":"gameplay-collapse","title":"Геймплей схлопнулся","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Ситуация, при которой комплексные системы схлопываются до тривиальных выводов, ввиду чего ресурсы, затраченные на разработку этих систем, оказались потрачены впустую","type":"text"}]}]}},{"id":"69864bb9-f53e-4a82-901f-d4f26732e501","slug":"difficulty","title":"Сложность","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Произведение вероятности совершить ошибку на цену этой ошибки","type":"text"}]}]}},{"id":"6f5a8925-4e48-4702-a6d1-7e50ca59b525","slug":"kelvin-moment","title":"Кельвин moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Требование проведения экспериментов, сбора статистики и прочих научных подтверждений таким тривиальным вещам как ","type":"text"},{"text":"\"нажатие трёх кнопок требует бОльших усилий, чем нажатие двух\"","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"См. ","type":"text"},{"text":"Видео Того Самого Келина не научны","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/nPwhWU0R29I","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}},{"id":"d1674b9f-2e05-4fb6-a94d-acf69a17170f","slug":"potential-challengeness","title":"Потенциальная челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Общая челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#general-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" - ","type":"text"},{"text":"реализованная","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Иными словами, то, что могло в игре быть, но этого нет","type":"text"}]}]}},{"id":"a2624356-ee3d-44ee-adc0-e3b12e571e48","slug":"realized-challengeness","title":"Реализованная челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Измеряется фактически существующими в игре ","type":"text"},{"text":"челленджами","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"5f626c81-fa38-40dc-b945-8438bd1d93c9","slug":"minmaxing","title":"Минмаксинг","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Стратегия, при которой игрок максимизирует одни аспекты ","type":"text"},{"text":"(например, урон)","type":"text","marks":[{"type":"italic"}]},{"text":", игнорируя или жертвуя другими, менее важными ","type":"text"},{"text":"(например, защита от огня)","type":"text","marks":[{"type":"italic"}]}]}]}},{"id":"8fd66ff1-0334-4c0c-bb68-417d7f9f7669","slug":"dark-meta","title":"Dark Meta","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Вид мета-прогрессии в рогаликах, при котором изначально игра более сложная (иногда непроходимо сложная), но по мере перманентной прокачки становится проще и проще","type":"text"}]}]}},{"id":"d359253f-419b-4b93-a60c-ea5c4d27d7a3","slug":"mechanics-in-vacuum","title":"Полезность механики зависит от контекста","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Механики в вакууме не являются ни плохими, ни хорошими. Они становятся таковыми, лишь находясь в контексте, в сочетании с другими существующими решениями. Создаёт ли это решение новый игровой опыт или же ломает то, что построено остальными механиками? Вот в чём вопрос","type":"text"}]}]}},{"id":"11f255db-4742-407e-a3e8-10d8a10afdfa","slug":"general-challengeness","title":"Общая челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Определяется всеми ","type":"text"},{"text":"челленджами","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", которые возможны из описания игровых механик. Независимо от того, представлены они в игре или нет, форсит ли игра их выполнять или нет итд.","type":"text"}]}]}},{"id":"02555c29-1687-4c2b-bbfb-02c917dabd95","slug":"challenge","title":"Челлендж","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Любая задача, требующая от игрока применения определённого навыка и допускающая вероятность ошибки","type":"text"}]}]}},{"id":"c4814ee8-1861-477e-9028-ccd6cc244bd4","slug":"there-is-that-thing","title":"В игре есть, в игре можно","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Само по себе ","type":"text"},{"text":"\"в игре есть\"","type":"text","marks":[{"type":"italic"}]},{"text":" не является буллшитом, но зачастую люди приводят в контраргумент штуки, которые ничего не меняют","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, существование в ","type":"text"},{"text":"Gunfire Reborn","type":"text","marks":[{"type":"bold"}]},{"text":" перка на 3 дэша не отменяет того, что базовая мобильность персонажа крайне мала, а вся боевая система дизайнится с расчётом на базового персонажа, а не под этот перк - ведь он может не выпасть, и игра должна быть проходима без него","type":"text"}]},{"type":"paragraph","content":[{"text":"Также часто приводят и ","type":"text"},{"text":"иррациональные штуки","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", ","type":"text"},{"text":"опциональные механики","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" итд","type":"text"}]},{"type":"paragraph","content":[{"text":"Поэтому будьте внимательны - как минимум, если хочется такое написать, вместо утверждения с порога лучше спросить ","type":"text"},{"text":"\"а что насчёт X?\"","type":"text","marks":[{"type":"italic"}]},{"text":". Скорее всего, X не упомянулся по вышеописанной причине","type":"text"}]}]}},{"id":"38f4fc3e-d006-42d4-91b8-6bc1ef88bd74","slug":"dyssynergy","title":"Диссинергия","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Воздействие двух элементов друг на друга таким образом, что их объединённый эффект ниже, чем по отдельности","type":"text"}]},{"type":"paragraph","content":[{"text":"Например","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"+5 к урону, но -5 к скорости атаки\" аннулирует \"+5 к скорости атаки, но -5 к урону\". Тогда как последний, к примеру, можно было использовать в ","type":"text"},{"text":"синергии","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#synergy","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" с on-hit эффектами","type":"text"}]}]}]}]}},{"id":"eb17db77-d69f-4d6f-91dc-5701b24ca194","slug":"people-are-used-to-it","title":"Люди уже привыкли","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"То, что люди привыкли к той или иной проблеме - не значит, что этой проблемы нет.","type":"text"}]},{"type":"paragraph","content":[{"text":"Пример:","type":"text","marks":[{"type":"bold"}]},{"text":" в ","type":"text"},{"text":"Dead Cells","type":"text","marks":[{"type":"bold"}]},{"text":" некоторые мобы иногда ломают поведение при парировании. Если игрок этого не знает, он может из-за этого заруинить забег. К этому можно привыкнуть, но это не значит, что проблемы нет и что её нельзя пофиксить","type":"text"}]}]}},{"id":"9e158fa2-3f9e-433c-8420-87e5db2f25dc","slug":"this-game-is-about-x","title":"Эта игра про X","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Тейк \"игра про Х\" в большинстве случаев используется людьми в следующих целях:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Понизить планку оценивания до уровня, когда игра до неё начинает дотягивать, не желая признавать, что игра может быть гораздо большим","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Выставить один из аспектов игры, который человеку понравился за ключевой, игнорируя то, что это комплексный продукт, а аудитория не ограничивается этим человеком","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"При критике одного аспекта переключаться на другой, где якобы проблем нет, при разборе следующего аспекта переключаться ещё куда-то - и так, пока не уйдём в луп","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игра про всё, что в ней есть","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"http://localhost:5173/glossary#games-as-a-whole","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разбор Elden Ring с разных перспектив","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/LoLljYUofWM","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"b1b591f3-f066-4203-bcf9-86dbeadeca2e","slug":"did-not-happen-for-me","title":"У меня не было","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Общая формула такого коммента: ","type":"text"},{"type":"hardBreak"},{"text":"%объективное_утверждение% говно, потому что %субъективное_обоснование%","type":"text","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"text":"Ваш личный опыт - это ваш личный опыт. Если вам повезло не столкнуться с проблемой - это не значит, что других она не коснулась. И не значит, что люди, у которых опыт получился негативным, являются криворукими дураками или типа того","type":"text"}]},{"type":"paragraph","content":[{"text":"В своём анализе я описываю свойства игры и что из них следует. Это не значит, что часть про \"следует\" произойдёт абсолютно с каждым игроком, но это может произойти, а посему есть смысл прикинуть, как сделать лучше","type":"text"}]}]}},{"id":"60dd9a91-3e54-4c1f-bc84-8efb7fe43bde","slug":"games-as-a-whole","title":"Игра - не про X, Y или Z. Она про всё","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Часто, когда анализируется тот или иной аспект в крупной игре, приходят люди и говорят \"эта игра не про боёвку, она про билдострой\". Потом разби��ается билдострой, приходят другие и говорят \"эта игра не про билды, она про эксплоринг\". И так пока круг не замкнётся","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот, в своём анализе я отталкиваюсь от того, что игра - про всё, что в ней есть","type":"text"}]},{"type":"paragraph","content":[{"text":"Одно дело, когда в игре, скажем, отсутствует боёвка. Возьмём к примеру условный рогалик ","type":"text"},{"text":"Megaloot","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2440380/Megaloot/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - здесь у нас буквально идёт автобой. Будет неразумно называть проблемой отсутствие каких-нибудь активных кнопок с необходимостью ими как-то жонглировать и т.д. Это, возможно, было бы неплохо заиметь, но здесь боёвки буквально нет. Разработчик не тратил на это ресурсы, поэтому вопросов нет","type":"text"}]},{"type":"paragraph","content":[{"text":"Совсем другое дело, когда в игре присутствует выраженная боевая система с продвинутыми интеракциями скиллов - такое стоит анализировать. И если какой-то из продвинутых аспектов проседает, либо одно аннулирует другое ","type":"text"},{"text":"(что является регулярной историей, например, в тех же диаблоидах, где билдострой аннулирует боёвку)","type":"text","marks":[{"type":"italic"}]},{"text":", то это нужно разбирать и искать варианты, как улучшить, а не говорить \"это игра про другое\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Если в игре какой-то аспект хромает, и подавляющее большинство игроков действительно считает, что игра действительно не про это, то налицо впустую потраченные разработчиком ресурсы, которые только отвлекают от той самой \"сути\". Соответственно, этот аспект нужно либо как-то фиксить и дорабатывать, чтобы люди перестали считать это рудиментом и пытаться нивелировать его присутствие, либо выкидывать его целиком","type":"text"}]},{"type":"paragraph","content":[{"text":"Так, например, я категорически не согласен с позицией ","type":"text"},{"text":"\"диаблоиды - игры про райтклик\"","type":"text","marks":[{"type":"italic"}]},{"text":". Студии вкладывают огромное количество денег в проработку механической составляющей скиллов - их разнообразие, взаимодействие итд, чтобы потом дядя Вася сказал ","type":"text"},{"text":"\"где мой фликер страйк, мне эта дрочка кнопок не упала\". ","type":"text","marks":[{"type":"italic"}]},{"text":"Соответственно, у диаблоидов в рамках позиции \"игра - про всё\" есть два пути","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"либо дорабатывать боёвку, как я предлагал ","type":"text"},{"text":"в обзоре Path of Exile 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/HA-yrnl7sKc?si=IA1WAipcVxsOWCbq","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"либо принять эту позицию и делать что-то в духе ","type":"text"},{"text":"Vampire Survivors","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1794680/Vampire_Survivors/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", только с картами и продвинутой, продолжительной прогрессией. Вампиры с закосом под Diablo, к слову, ","type":"text"},{"text":"уже существуют","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2218750/Halls_of_Torment/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - осталось прогрессию подтянуть","type":"text"}]}]}]}]}},{"id":"f812da7e-1b6a-402d-b930-285b544699ce","slug":"exploits-are-actually-good","title":"\"Абузы\" - окна для интересного геймплея","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Если в игре что-то выглядит как абуз, то прежде, чем это \"фиксить\", стоит подумать - а можно ли это как-то обыграть?","type":"text"}]},{"type":"paragraph","content":[{"text":"Нередко такие штуки могут создать уникальный геймплей, а попытки их \"забалансить\" результируют в шаблонном продукте","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Не забирай у игроков свободу выбора","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/shorts/um7QZeA7CDY","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"1bb576bb-76f0-45d5-9ef5-e33e255b8498","slug":"i-have-another-definition","title":"У меня другие определения","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Иногда люди пишут, что кто-то несёт лютую ахинею, а затем выясняется, что у них своё определение слов. Да даже не \"своё\", а в целом другое, не соответствующее тому, которое использовал собеседник","type":"text"}]},{"type":"paragraph","content":[{"text":"Рассуждения строятся в рамках той терминологии, которая обозначена утверждающим. Соответственно, корректность выводов нужно оценивать в рамках заданной терминологии","type":"text"}]},{"type":"paragraph","content":[{"text":"Если термин не обозначен и не выводится однозначно из утверждений, то перед этим стоит спросить, что человек имеет в виду под словом X. А не сразу бросаться говорить ему, какой он дурак","type":"text"}]},{"type":"paragraph","content":[{"text":"Изобретать свои термины для удобства, к слову - абсолютно нормально. Так, например, даже слово \"гравитация\" у того же Ньютона и Эйнштейна имеет абсолютно разное значение. Если вы не готовы это принять, то дискуссия с вами невозможна, и единственное, что получится из коммуникации - многочасовой срач за определения, который ни к чему не приведёт","type":"text"}]}]}},{"id":"7147a972-76bb-49da-80bf-a0c4041fa792","slug":"it-has-always-been-like-that","title":"В прошлой части/игре/других играх жанра так было","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"То, что где-то что-то когда-то было, не значит, что это хорошо","type":"text"}]},{"type":"paragraph","content":[{"text":"И даже если к этому привыкли, это не значит, что так и должно быть дальше","type":"text"}]},{"type":"paragraph","content":[{"text":"Чаще всего данной фразой оправдывают наличие каких-либо хреновых решений, называя их ","type":"text"},{"text":"\"наследие серии\", \"сутью жанра\"","type":"text","marks":[{"type":"italic"}]},{"text":" итд","type":"text"}]},{"type":"paragraph","content":[{"text":"Быть консерватором в такой молодой индустрии, как видеоигры - зашквар. Если бы разработчики придерживались таких тейков, то мы бы до сих пор играли только в ретро-платформеры и ASCII-рогалики. Ибо каждый качественный скачок вперёд всегда сопровождался фразой ","type":"text"},{"text":"\"а что, если\"","type":"text","marks":[{"type":"italic"}]},{"text":" или ","type":"text"},{"text":"\"нахрена оно вот так, если можно вот так и будет лучше\"","type":"text","marks":[{"type":"italic"}]}]}]}},{"id":"b00f757e-5d59-4502-a30f-4c8fbd142405","slug":"i-see-that-author-is-retarded","title":"Сразу видно, автор...","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Критикуй конкретные утверждения, а не додумывай, почему автор что-то сказал","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Хорошо: ","type":"text"},{"text":"\"этот противник получает повышенный урон от рипоста, так что его можно не ковырять долго вилкой\"","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Плохо: ","type":"text"},{"text":"\"сразу видно, автор никогда не играл в подобные игры и посему несёт бредик про ковыряние вилкой\"","type":"text","marks":[{"type":"italic"}]}]}]}]},{"type":"paragraph","content":[{"text":"Последнее - инста бан без прочтения. Подобные комментарии не только бессодержательны и тратят впустую время на токсины, но и в большинстве случаев не соответствуют действительности, поскольку выводы об авторе строятся лишь из того, что человек успел увидеть бегло в профиле канала (если вообще его смотрел)","type":"text"}]}]}},{"id":"08e26ca1-d4ff-4641-ab99-6d9204eb935a","slug":"subjectivity","title":"Всё субъективно, объективности не существует","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Во-первых, если вы считаете, что ","type":"text"},{"text":"\"всё в нашем мире субъективно\"","type":"text","marks":[{"type":"italic"}]},{"text":", то вы ","type":"text"},{"text":"дифичент","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/M6vD-iLc_PI?t=62","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}},{"type":"bold"}]},{"text":", поскольку уже сама фраза ","type":"text"},{"text":"\"всё субъективно\"","type":"text","marks":[{"type":"italic"}]},{"text":" содержит в себе парадокс","type":"text"}]},{"type":"paragraph","content":[{"text":"Если всё субъективно, то и само это утверждение тоже. А это либо так, и тогда субъективизм несостоятелен; либо не так - и тогда это неверное утверждение","type":"text"}]},{"type":"paragraph","content":[{"text":"С субъективным подходом невозможно сделать ни один полезный вывод. Если бы всё в нашем мире было субъективно, то в нём царил бы полный хаос. Однако же, мы живём в обществе, которое как-то структурировано; мы имеем науку, которая, хоть и имеет дыры в некоторых вопросах, работает безотносительно нашего мнения; мы имеем такую штуку как ","type":"text"},{"text":"\"статистика\"","type":"text","marks":[{"type":"italic"}]},{"text":" и ","type":"text"},{"text":"\"теория вероятности\"","type":"text","marks":[{"type":"italic"}]},{"text":" итд.","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему, доля субъективных утверждений минимизируется, а приоритет отдаётся логике и фактом","type":"text"}]},{"type":"paragraph","content":[{"text":"Ну и наглядно разницу между \"субъективно\" и \"объективно\"","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Субъективно: ","type":"text","marks":[{"type":"bold"}]},{"text":"Мне не понравилась %штука_нейм%","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Объективно: ","type":"text","marks":[{"type":"bold"}]},{"text":"%штука_нейм% содержит %противоречие_нейм% и делает %такой_то_геймплей% невыгодным","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Субъективно:","type":"text","marks":[{"type":"bold"}]},{"text":" Я играл ","type":"text"},{"text":"%вот так-то%","type":"text","marks":[{"type":"italic"}]},{"text":" и остался недоволен","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Объективно: ","type":"text","marks":[{"type":"bold"}]},{"text":"%штука_нейм%","type":"text","marks":[{"type":"italic"}]},{"text":" и ","type":"text"},{"text":"%другая_штука_нейм%","type":"text","marks":[{"type":"italic"}]},{"text":" приводят к тому, что игрок с бОльшей вероятностью будет играть ","type":"text"},{"text":"%вот так-то%","type":"text","marks":[{"type":"italic"}]}]}]}]}]}},{"id":"399eb820-3c2b-470b-b7b6-ae572c366c68","slug":"but-the-game-is-selling","title":"Но ведь игра продаётся","category":"bullshit_trope","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Качество продукта и его некое \"логическое, геймдизайнерское совершенство\" являются лишь одним из компонентов, влияющих на коммерческий успех","type":"text"}]},{"type":"paragraph","content":[{"text":"Сюда также относится:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Другие составляющие, такие как сюжет, графика итд.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Востребованность таких игр на рынке. Например, даже самые пососные сурвайвал-игры разлетаются как горячие пирожки, несмотря на то, что сделаны на коленке и делают то же самое, что десяток подобных проектов до этого","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Отсутствие конкуренции. Почти как прошлый пункт, но чуть с другой стороны. Если у людей есть интерес к чему-то, но при этом нет достойных проектов, то и такой себе проект люди охотно купят","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Маркетинг. Сюда входит как активная реклама, так и просто ","type":"text"},{"text":"\"это игра от создателей Dark Souls\"","type":"text","marks":[{"type":"italic"}]},{"text":" или ","type":"text"},{"text":"\"это вампиры по Deep Rock Galactic\"","type":"text","marks":[{"type":"italic"}]},{"text":". Cyberpunk 2077, к слову, продался в рекордных количествах, несмотря на то, что его релизное состояние было отвратительным","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Факторы, которые в отдельно взятом обсуждении могли не рассматриваться, т.к. фокус был на чём-то конкретном. К примеру, ","type":"text"},{"text":"\"разбор боёвки без билдостроения\"","type":"text","marks":[{"type":"italic"}]},{"text":" или ","type":"text"},{"text":"\"первый взгляд без разбора эндгейма\"","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"и ещё куча других факторов","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Посему нет смысла говорить \"игра продалась, значит, критика геймдизайна идёт лесом\"","type":"text"}]}]}},{"id":"ba442f11-25bb-45cc-9222-d59bb066c53d","slug":"criticism-should-be-constructive","title":"Критика должна быть конструктивной","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Многие люди при слове \"критика\" представляют ворчащего деда, который вечно всем недоволен","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот, критика - не об этом","type":"text"}]},{"type":"paragraph","content":[{"text":"Критика должна нести в себе конструктивную цель. Если поднимается какая-то проблема - нужно не просто говорить ","type":"text"},{"text":"\"это плохо\"","type":"text","marks":[{"type":"italic"}]},{"text":", но и предложить возможные решения. Если идей по улучшению нет - то хотя бы пригласить остальных к диалогу","type":"text"}]},{"type":"paragraph","content":[{"text":"То же самое касается и критики критики","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Если вы считаете, что предложенные решения чем-то плохи - предложите лучше или хотя бы расскажите, что именно вас смущает и почему","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Если вы считаете, что какой-то из здесь перечисленных основополагающих принципов приводит к ложным выводам или в принципе обладает недостаточной предсказательной силой - предложите лучше или расскажите, почему","type":"text"}]}]}]}]}},{"id":"4b5a45a2-11c1-4400-b422-14d0b9c78d0b","slug":"cooperative-types","title":"4 вида кооператива","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Сразу ","type":"text"},{"text":"важные ","type":"text","marks":[{"type":"bold"}]},{"text":"оговорки:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"“Виды кооператива” — это короткая формулировка, которая сразу дает понять, что ","type":"text"},{"text":"речь именно про взаимодействие с тиммейтами","type":"text","marks":[{"type":"bold"}]},{"text":". Такое взаимодействие может быть не только в кооперативе, но и мультиплеере, главное, чтобы были тиммейты","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ни один из видов не лучше и не хуже других","type":"text","marks":[{"type":"bold"}]},{"text":". При этом каждый из вариантов можно сделать плохо или хорошо. Причем вот это плохо/хорошо достигается разными способами","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разные виды коопов нравятся разным людям","type":"text","marks":[{"type":"bold"}]},{"text":", это нормально. Такая классификация в том числе помогает понимать, а что нравится вам, и как это понятно объяснить остальным","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Для всех видов кооператива важно не забывать, что ","type":"text"},{"text":"геймплей каждого конкретного игрока должен быть интересен","type":"text","marks":[{"type":"bold"}]},{"text":". Это может быть незаметно за общей комплексностью, но если чей-то игровой опыт по итогу уныл, примитивен и репитативен — это очень серьезная проблема. ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В играх часто сочетаются разные виды кооперативных взаимодействий, как чередованием, так и комбинированием. Поэтому ","type":"text"},{"text":"зачастую корректнее характеризовать конкретные сегменты","type":"text","marks":[{"type":"bold"}]},{"text":" ","type":"text"},{"text":"игры ","type":"text","marks":[{"type":"bold"}]},{"text":"отдельно друг от друга. Всю игру целиком можно описать, если этот вид коопа в ней очевидно основной или вообще единственный","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Сами виды:","type":"text"}]},{"type":"paragraph","content":[{"text":"Совместная игра","type":"text","marks":[{"type":"bold"}]},{"text":" — вы вместе играете в одну игру, разделяя ","type":"text"},{"text":"общий контекст и влияя на один и тот же мир","type":"text","marks":[{"type":"bold"}]},{"text":", возможно даже напрямую помогая другим игрокам, но не имеете необходимости как-то коммуницировать или активно следить за тиммейтами","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Division 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2221490/Tom_Clancys_The_Division_2/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Deep Rock Galactic","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/548430/Deep_Rock_Galactic/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spiritfarer","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/972660/Izdanie_Spiritfarer_Farewell/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если наличие тиммейтов дает свой импакт и он велик.","type":"text"},{"type":"hardBreak"},{"text":"Например:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Можно играть активнее и агрессивнее за счет разделения агра и ответственности","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Увеличено разнообразие билдов, за счет возможности разделения боевых задач и помощи другим тиммейтам. Есть разного рода саппорт-билды и билды, специализирующиеся на убийстве конкретных категорий мобов","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ты регулярно видишь и пользуешься результатами чужих трудов за счет того, что действия других игроков изменяют игровой мир","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игра активно подкидывает вам почву для обсуждений и комментариев, за счет поднимания каких-то тем в сюжете, создания вау моментов, смены сеттинга и множества отсылок","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Командная игра","type":"text","marks":[{"type":"bold"}]},{"text":" — вы ","type":"text"},{"text":"активно следите за своими тиммейтами","type":"text","marks":[{"type":"bold"}]},{"text":", за тем где они, что делают, что пытаются сделать, и ","type":"text"},{"text":"на основе этой информации сами принимаете решения","type":"text","marks":[{"type":"bold"}]},{"text":", как вам лучше отыгрывать","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helldivers 1","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/394510/HELLDIVERS_Dive_Harder_Edition/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Marvel Rivals","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2767030/Marvel_Rivals/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"ibb & obb","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/95400/ibb__obb/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если всем игрокам нужно следить за действиями друг друга и делать это нужно действительно активно.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры задач:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Правильно позиционироваться друг относительно друга: например нужно быть рядом, быть с правильной стороны, не перекрывать прицел, не подходить слишком близко, вовремя сходиться и расходиться, параллельно с этим куда-то двигаться","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Вовремя сейвить друг друга, например: накидывать барьер или закрывать щитом/грудью за секунду до потенциальной смерти, сбивать опасные проджектайлы, откидывать врага от тиммейта или наоборот в опасные моменты","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Одновременно атаковать одни и те же цели","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Намеренно не атаковать ту же цель, что и тиммейт, если это ему помешает. ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Использовать способности отталкивания, притягивания и другого передвижения противника, помогая тиммейтам, а не мешая им ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Не перекрывать способности друг друга, например не кидать свой стан, если видишь, что тиммейт ближе и из-за этого кинет свой стан раньше","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Бафать друг друга в момент, когда это будет наиболее эффективно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Коллаборативное взаимодействие","type":"text","marks":[{"type":"bold"}]},{"text":" — вы коммуницируете для ","type":"text"},{"text":"совместного принятия решений","type":"text","marks":[{"type":"bold"}]},{"text":" в игре ","type":"text"},{"text":"или для предложения каких-то внутри-игровых взаимодействий","type":"text","marks":[{"type":"bold"}]},{"text":". Проще говоря, вы обсуждаете или предлагаете дальнейшие действия в игре","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Divinity: Original Sin 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/435150/Divinity_Original_Sin_2__Definitive_Edition/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rabbit and Steel","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2132850/Rabbit_and_Steel/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"PlateUp!","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1599600/PlateUp/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если обсуждать и предлагать дальнейшие действия нужно часто, а итоговые решения и внутри-игровые взаимодействия значимы и интересны","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры задач:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Обсудить на какой квест пойти","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Обсудить как лучше прокачаться и закупиться, потенциально даже сначала предложив разойтись по разным торговцам, чтобы сразу видеть все варианты, что купить","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Придумать план по обкрадыванию торовца, распределив задачи, кто будет отвлекать жертву и потом даст себя осмотреть, кто будет отвлекать других NPC, чтобы они отвернулись или не дошли до места кражи, и кто сворует нужный лут, а потом сбежит с места преступления","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Придумать решение боевого или логического паззла","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Быстро заколлить что-то (от слова колл — призыв к действию). Например убийство, лечение, пуш, отступление или выбивание конкретных способностей из противника","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Сервисное общение","type":"text","marks":[{"type":"bold"}]},{"text":" — вы имеете разную информацию о ситуации в игре и коммуницируете, либо чтобы ","type":"text"},{"text":"лучше понять ситуацию","type":"text","marks":[{"type":"bold"}]},{"text":", либо чтобы дать ","type":"text"},{"text":"прямые инструкции","type":"text","marks":[{"type":"bold"}]},{"text":" для прохождения какого-то сегмента","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Keep Talking and Nobody Explodes","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/341800/Keep_Talking_and_Nobody_Explodes/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"We Were Here","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/bundle/12260/We_Were_Here_Series/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если хорошо обыграно само общение в моменты объяснения ситуации, передачи и выполнения инструкций","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры обыгрывания:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно быстро объяснять нестандартные сложные символы, из-за чего приходится подбирать потенциально забавные ассоциации","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно точно сообщить слово, но у него есть много созвучных вариантов. (пОроГ - пОроК - пАроК, итак - и так, ещЕ раз - ещЁ раз)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно сообщить об отсутствии слова на табло, но также могут быть варианты “НИЧЕГО”, “ПУСТО”, “ЭКРАН” ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В прямую инструкцию вроде “Напиши X” встраивается слово, которое может быть воспринято, как продолжение инструкции — “Напиши ЕЩЁ РАЗ”","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нужно объяснить очень странную картину, но на ней важно сразу множество деталей и объяснения вроде “Птица с панцирем улитки на спине”, будет недостаточно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"4 вида кооператива в играх","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/dM6yBonVR3A","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"c42d8596-a8ed-4917-a8e9-3f176584d295","slug":"game-properties-over-subjective-experience","title":"Свойства игры > личный опыт","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"При разборе гейм-дизайна следует отталкиваться от самих свойств игры и смотреть, что из них следует, а не от того, как в игру играл отдельный игрок","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, если в игре с огромным количеством развилок в одной из них находится очень важный для прохождения предмет, без которого игровой опыт будет значительно хуже - это проблема. Если кому-то в такой игре повезло пойти в правильную развилку, это не отменяет того, что есть огромная вероятность пойти в неправильную и заруинить себе прохождение","type":"text"}]},{"type":"paragraph","content":[{"text":"Также стоит разграничивать фидбек, причина которому лежит в отдельно взятом индивиде, от фидбека, причина которому лежит в самой игре","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, если при наличии открытого коридора перед глазами отдельно взятый игрок шёл в стену 20 часов и сказал \"игра скучная\" - этот фидбек нерелевантен. Если же сама игра спрятала нужный проход где-то в тени, и игрок не понял, куда идти - это проблема игры. И, скорее всего, такой фидбек будет массовым","type":"text"}]}]}},{"id":"c0c326c6-5ad8-41c3-9ba9-4aeebce48ee2","slug":"game","title":"Игра","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"В контексте рассуждений и дальнейших определений под играми понимается форма медиа, представляющая собой интерактивное развлечение, которое ставит перед игроком различные задачи, выполняемые посредством заданных правил и ","type":"text"},{"text":"механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", позволяющих взаимодействовать с игровым миром в широком смысле (то есть стол в карточной игре — тоже игровой мир), и вознаграждает за выполнение этих задач","type":"text"},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"Это определение призвано лишь пояснить область рассуждений и их применимости. Оно не является идеальным исчерпывающим набором критериев для определения, что игрой является, а что нет","type":"text"}]}]}},{"id":"c8ae4569-90d7-46e1-9ec1-aa122f4a2eb0","slug":"challengeness","title":"Челленджовость","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Метрика, которая характеризуется количеством уникальных ","type":"text"},{"text":"челленджей","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в игре","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Общая челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#general-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Реализованная челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Потенциальная челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#potential-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"c6526fb0-c836-4d8a-a3f3-ecfa25376f51","slug":"rational-agent","title":"Рациональный агент","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Абстрактный агент, действующий оптимальным образом для достижения результата в рамках рассматриваемой цели","type":"text"}]},{"type":"paragraph","content":[{"text":"Стоит отметить ряд моментов","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Рациональный агент применяется к заданной интересующей цели, а не обязательно к одному лишь общему \"пройти игру\". Так, например, в условной DmC люди не ставят задачей \"просто пройти игру\", они ставят задачу \"пройти игру красиво\". Соответственно, анализировать рациональность нужно в рамках этой задачи","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Рациональный агент - не всезнайка. Если какая-то информация на момент принятия решения недоступна, нельзя учитывать её в расчётах","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Рациональность учитывает не только сухую эффективность, но и сложность исполнения, освоения итд. Т.е. если действие X даёт в 10 раз бОльший результат, чем Y, но при этом X сопоставимо сложнее исполнить, то рациональность этих двух действий равна","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Стоит, однако, отметить, что при математически равной рациональности игроки, скорее всего, отдадут предпочтение более стабильной стратегии","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также ","type":"text"},{"text":"3 типа рациональности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rationality-types","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"bc7eac1d-b2d6-4c1f-b0fe-e08dbac29c3c","slug":"orthogonality","title":"Ортогональность","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Свойство элементов игры, означающее их независимость друг от друга","type":"text"}]},{"type":"paragraph","content":[{"text":"Представим две игровые системы в качестве осей X и Y, значения которых характеризуют утилизацию этих игровых систем","type":"text"}]},{"type":"paragraph","content":[{"text":"Для достижения успеха игрок должен дойти до определённой пороговой зоны, которая, начинается, скажем, с точки (3; 2)","type":"text"}]},{"type":"paragraph","content":[{"text":"Если игровые системы ортогональны по отношению друг к другу, это означает, что игрок не сможет добраться до этой зоны, замастерив лишь одну систему","type":"text"}]},{"type":"paragraph","content":[{"text":"Данная концепция полезна при проектировании. Если задачей разработчика стоит не допустить аннулирование, скажем, боевой системы билдостроением, то в эти системы сразу стоит закладывать ортогональные ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Примеры ортогональности:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок мог бы пройти игру чисто на скилле, научившись идеально избегать атак противников. Однако, враги спавнятся с определённым интервалом, а по мере забега становятся жирнее. Из-за чего, если игрок игнорирует билдостроение, то он перестанет успевать зачищать мобов и его задавит числом","type":"text"}]}]}]}]}},{"id":"500acada-5524-4a84-ab44-a2029afccb94","slug":"games-are-about-gameplay","title":"Геймплей первичен","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Геймплей - ключевой аспект ","type":"text"},{"text":"игр","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#game","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", отличающий их от других форм медиа","type":"text"}]},{"type":"paragraph","content":[{"text":"Именно качество реализации геймплея определяет, насколько полученный продукт хорош, как игра","type":"text"}]},{"type":"paragraph","content":[{"text":"Это не означает, что остальные факторы, вроде графики, сюжета и т.д. не важны. Это значит, что любой, даже чисто сюжетной игре, нужно в полной мере использовать геймплей","type":"text"}]},{"type":"paragraph","content":[{"text":"Этот принцип касается не только \"сугубо геймплейных\" жанров вроде рогаликов и метроидваний, но и в том числе тех, что ориентированы на нарратив","type":"text"}]},{"type":"paragraph","content":[{"text":"В контексте нарратива геймплей является очень сильным инструментом для донесения какого-либо опыта, чувств итд.","type":"text"}]},{"type":"paragraph","content":[{"text":"В то время как книги и фильмы предлагают тебе просто наблюдать за происходящим, игры позволяют тебе это прочувствовать на себе, непосредственно проживать и испытывать, как минимум на уровне принятия решений","type":"text"}]},{"type":"paragraph","content":[{"text":"Если же сюжетно-ориентированная игра строится по принципу ","type":"text"},{"text":"“игры - это кино, где геймплей выступает в качестве экшн-сцен”","type":"text","marks":[{"type":"italic"}]},{"text":", то эта игра не пользуется сильнейшим доступным инструментом воздействия на игрока в полной мере, и по итогу плоха, как игра","type":"text"}]},{"type":"paragraph","content":[{"text":"Игра с плохим геймплеем, но хорошим сюжетом - это всегда упущенный потенциал","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры использования геймплея для усиления нарратива: ","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"It Takes Two","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1426210/It_Takes_Two/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" в нашумевшем фрагменте со слонихой заставляет игроков своими руками несколько раз её разорвать, несмотря на вопли и мольбы остановиться. И это не просто разовый выбор в диалоге с катсценой после - это именно длящийся момент, где тебе нужно быстро многократно нажимать на кнопку, продолжая раз за разом подтверждать свои намерения, что значительно усиливает эмоциональный эффект за счёт большей связи с происходящими действиями","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"What Remains of Edith Finch","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/501300/What_Remains_of_Edith_Finch/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", хоть и является симулятором ходьбы, подаёт историю не только через озвучку рассказчиком, но и через геймплей. Например, в главе про мальчика, который раскачался на качелях и улетел с обрыва, ты не просто слушаешь/смотришь эту историю - тебе самому предстоит раскачаться","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"Dragon’s Dogma 2","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/2054970/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" выбор стороны в конфликте принимается через непосредственно нанесение урона тем персонажам, кого ты считаешь противниками. Подобное очень сильно способствует тому, чтобы игрок еще больше ассоциировал себя с персонажем и не было этой четкой грани, что сюжет отдельно, геймплей отдельно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Тот Самый Клуб сгорел с книжки для игровых сценаристов","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/CJE_BcGthUw?si=MCb6iJk92-2EweKf&t=219","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Сеттинг и сюжет - не отговорка","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#setting-and-story-is-not-an-excuse","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"c0c5a74d-8aef-49bd-b0d2-ecee90bb3c13","slug":"rationality-types","title":"3 типа рациональности","category":"classifications","content":{"type":"doc","content":[{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В игре есть одна доминирующая стратегия, которая может протащить всю игру","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В игре есть N стратегий, доминация которых чередуется по мере прохождения и определяется статичными факторами","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Доминирующая стратегия определяется в моменте, меняясь от динамических факторов","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примеры:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Меч на 1000 урона vs мечи на 100 урона при условии, что у противников нет контрмер на первый","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разные виды оружия наносят разный стихийный урон, а у противников разные стихийные резисты","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Противник чередует свои атаки в случайном порядке. Часть атак можно избежать несколькими способами. Но засчёт случайного порядка, определённые способы уворота на момент тех или иных атак могут быть недоступны, либо их сложнее исполнить","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также: ","type":"text"},{"text":"рациональный агент","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/glossary#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"b47723a6-0525-41f5-bddc-4dad2c74a02f","slug":"depth-vs-breadth","title":"Глубина vs Ширина","category":"classifications","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в ширину","type":"text","marks":[{"type":"bold"}]},{"text":" - добавление в игру нового контента, который является альтернативой, либо дополнением к уже имеющемуся","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в глубину","type":"text","marks":[{"type":"bold"}]},{"text":" - модернизация имеющегося и/или добавление нового контента, делающие игровой процесс более продуманным","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примеры:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в ширину","type":"text","marks":[{"type":"bold"}]},{"text":": добавление новых играбельных персонажей, новых локаций, новых квестов","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Развитие ","type":"text"},{"text":"в глубину","type":"text","marks":[{"type":"bold"}]},{"text":": добавление выгодных интеракций между стихиями, засчёт чего игрок захочет их комбинировать; добавление шкалы остроты оружия, необходимой для блокирования и нанесения урона с возможностью её восполнения в бою, создавая тем самым менеджмент этой остроты","type":"text"}]}]}]}]}},{"id":"bcaeab60-9518-4028-b924-92eabf6324bc","slug":"service-work","title":"Служебная работа","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Совокупность рутинных или технических операций, которые не являются частью основных ","type":"text"},{"text":"челленджей","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/glossary#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" игры и не требуют от игрока существенных навыков, планирования или принятия интересных решений","type":"text"}]},{"type":"paragraph","content":[{"text":"Часто эти операции связаны с обслуживанием внутриигровых ресурсов, инвентаря, интерфейсов и т.п. и служат лишь для поддержания рабочего состояния игрового процесса, но не вносят в него нового опыта","type":"text"}]}]}},{"id":"7e936df6-5cf0-43ea-af7a-e7683acd11e7","slug":"neon-abyss-moment","title":"\"Neon Abyss\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Реализация билдостроения, при которой всё синергирует со всем и любая конфигурация персонажа эффективна. Соответственно, принятие игроком решений как таковое отсутствует, а конечные билды едва ли чем-то отличаются друг от друга","type":"text"}]},{"type":"paragraph","content":[{"text":"Названа в честь рогалика ","type":"text"},{"text":"Neon Abyss","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/788100/Neon_Abyss/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" как яркого примера подобной ситуации","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Как делать крутое билдостроение?","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/pmYTndWoWgQ","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"073dd9d2-b900-4e4f-b958-e5944e149dd2","slug":"genre-is-secondary","title":"Жанры вторичны","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Жанры вторичны по отношению к общим принципам, по которым строятся игры","type":"text"}]},{"type":"paragraph","content":[{"text":"Под общими принципами имеется в виду то, что эксплуатирует триггеры тех или иных эмоций в человеке. Например, удовольствие от видимого прогресса, азарт итд. Подобные штуки могут быть достигнуты совершенно разными способами, и для этого необязательно делать по уже известному шаблону, внося в игру в том числе и лишние элементы, ведь так делают все","type":"text"}]},{"type":"paragraph","content":[{"text":"Соответственно, нет ничего плохого и в том, чтобы предложить игре какое-либо изменение, которое \"перенесёт\" игру в другой жанр, если так в ней станет меньше противоречий и она станет лучше эксплуатировать выбранные триггеры","type":"text"}]},{"type":"paragraph","content":[{"text":"Рогалики, диаблоиды, мобы, пошаговые рпг, соулслайки - если их декомпозировать, все эти игры состоят практически из одних и тех же систем, просто в разных пропорциях и с разной углублённостью","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему контртейки \"это уже другая игра будет\" в контексте фикса тех или иных проблем не принимаются. Обсуждать нужно, хороша ли игра сама по себе как совокупность связанных между собой игровых систем, а не насколько это каноничный пошаговый рогалик","type":"text"}]},{"type":"paragraph","content":[{"text":"То же самое касается, на самом деле, и синонимов вроде \"наследия серии\" итд. Фанаты \"серии\" привыкают к тем или иным проблемам и перестают их замечать. А те, для кого проблемы критичны, отсеиваются и больше не дают свой фидбек. Ввиду чего образуется пузырь. Но если сломать этот пузырь и всё же что-то изменить, то велика вероятность, что \"серия\" на самом деле интересна куда бОльшему числу игроков, просто они обходили её стороной","type":"text"}]}]}},{"id":"dbd39421-4991-469a-b2d8-c4ce089baef5","slug":"strive-for-perfection","title":"Идеал недостижим, но к нему можно стремиться","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"\"Идеальных вещей в нашем мире не существует\"","type":"text","marks":[{"type":"italic"}]},{"text":" - это справедливое утверждение, которое, к сожалению, часто используют для того, чтобы сказать, что критики занимаются ерундой, что и так всё хорошо, что не нужно ничего улучшать или это вовсе невозможно","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот, идеальных вещей действительно не существует. Но если в продукте есть места, которые можно улучшить - это стоит сделать. Если таких мест не наблюдается, но присутствуют какие-либо противоречия в дизайне - можно порассуждать над альтернативами","type":"text"}]}]}},{"id":"c6b5c284-4932-4349-bff6-f1f56706931c","slug":"emergence","title":"Эмерджентность","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Наличие у системы свойств, не присущих её компонентам по отдельности","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры эмерджентности:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"Brotato","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1942280/Brotato/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" такие характеристики как \"высокая регенерация HP\" или \"отражение урона\" по отдельности могут присутствовать у кого угодно. Но если соединить их вместе, то появится возможность отыгрывать \"быка\" - вместо использования оружия умышленно налетать на врагов, наносить им урон обраткой и быстро восстанавливать здоровье обратно","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Эмерджентность может быть ","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"как явно заданной - например, появление новых свойств у некоторых комбинаций амулетов в ","type":"text"},{"text":"Hollow Knight","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/367520/Hollow_Knight/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" вроде восстановления маны через паучков","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"так и неявно появляться из синергий - например, продление кадров неуязвимости после получения урона вкупе с ускорением лечения может дать игроку возможность лечиться в любое время","type":"text"}]}]}]}]}},{"id":"5691aee4-fb32-434d-94df-2f05b99bbb17","slug":"mechanics","title":"Механика","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Дискретный минимальный элемент игрового процесса, который определяется набором конкретных правил или параметров и выполнен таким образом, что он может быть ясно идентифицирован и изолирован в рамках более широкой системы игры","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры механик: атака; статус-эффект; дивиденды в Balatro; стресс в Darkest Dungeon","type":"text"}]}]}},{"id":"e9795f04-dd38-4e87-b8aa-fea0afdb7f6a","slug":"qol-should-not-have-opportunity-cost","title":"QoL не должен стоить геймплейных возможностей","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Игрок не должен выбирать между тем, видеть себя на карте ","type":"text"},{"text":"(в игре, где вокруг этого знания не выстроен какой-то геймплей)","type":"text","marks":[{"type":"italic"}]},{"text":" или иметь больше урона. Даже если это выбор между \"иммерсивным\" и обычным прохождением игры. Даже если этому придумано какое-то нарративное обоснование","type":"text"}]},{"type":"paragraph","content":[{"text":"Это может быть опцией, но включение ","type":"text"},{"text":"QoL","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"quality-of-life","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" не должно требовать от игрока отказа от геймплейных возможностей","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Сеттинг и сюжет - не отговорка","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#setting-and-story-is-not-an-excuse","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"8a186983-09e9-404a-90d4-b3fe690e25df","slug":"fun-should-be-rewarded","title":"\"Весёлый\" геймплей должен вознаграждаться","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Если в игре нерационально пользоваться арсеналом инструментов или производить какие-то сложные действия, а рациональный геймплей сводится к скучному спаму двух кнопок - это проблема игры, поскольку в таком случае у нас 3 варианта исходов:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок, который проактивно играет \"весело\" безотносительно выгоды, получит удовольствие и так, и так","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок, который плывёт по течению и играет рационально, получит скучный игровой опыт","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игрок, который хочет играть весело, но видит, что игра за это не вознаграждает, расстроится","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"И если это пофиксить, то для первого ничего не изменится, а остальным станет лучше","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Адвокат Supergiant Russia критикует мой обзор Hades","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/WBTeef9tI3M","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"2232dae7-6ee9-47af-b8f3-cad9f15b1866","slug":"quality-of-life","title":"Quality of Life (QoL)","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Геймдизайнерские и технические решения, сделанные для удобства игрока и/или упрощения ","type":"text"},{"text":"служебной работы","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/glossary#service-work","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Примеры:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Кнопка \"Отсортировать предметы\" в инвентаре RPG-игры","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ускорение анимаций в ","type":"text"},{"text":"Slay the Spire","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/646570/Slay_the_Spire/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"a56b7fed-0259-4770-98bd-c735f4c95993","slug":"synergy","title":"Синергия","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Воздействие двух элементов друг на друга таким образом, что их объединённый эффект превышает сумму эффектов по отдельности","type":"text"}]},{"type":"paragraph","content":[{"text":"Например","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Удвоенная скорость атаки и удвоенный урон вместе дают четырёхкратный прирост DPS. Тогда как по отдельности выходит трёхкратный (100+100+100)","type":"text"}]}]}]}]}},{"id":"3e34c301-e2df-4741-9bc6-2ebb219ee2f5","slug":"cargo-cult","title":"Карго-культ","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Общее понятие, не связанное непосредственно с геймдизайном, означающее поверхностную имитацию чего-либо без глубинного понимания причинно-следственных связей в надежде получить схожие с объектом копирования результаты","type":"text"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"text":"Отсылает термин к событиям второй мировой войны, когда на островах Меланезии размещались военные базы и аэропорты, через которые доставляли оружие, припасы, одежду и другие грузы. Часть этих вещей доставалась коренным жителям этих островов, как проводникам","type":"text"}]},{"type":"paragraph","content":[{"text":"Многие из них тогда видели все это впервые. И будучи неспособными объяснить происхождение этих грузов (cargo), кроме как проявлением чуда, стали верить в волшебную силу техники и других объектов","type":"text"}]},{"type":"paragraph","content":[{"text":"Когда закончилась война и поток грузов прекратился, местные жители решили, что, копируя манеры и постройки \"чужаков\", смогут расположить к себе духов, — и стали имитировать поведение военных: размечали взлетно-посадочные полосы, строили самолеты из пальм и соломы, делали наушники из кокосов, ружья из пало��, ходили строем и рисовали на себе ордена и надписи USA. Делали это в надежде снова получить \"небесные дары\"","type":"text"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"text":"В контексте игр карго-культом можно назвать ситуации, когда какие-то механики или другие аспекты заимствуют у других проектов, без понимания причин актуальности этих элементов в рамках контекста игры","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, перенос механики потери душ при смерти из солсов в абсолютно линейную игру. Потерянные души дополнительно мотивируют игрока после смерти пойти именно туда, где он только что умер, и в рамках нелинейных солсов эта дополнительная мотивация смысл имеет. В рамках же линейной игры у игрока в любом случае только один вариант, куда ему двигаться, из-за чего дополнительные бонусы к выбору, куда пойти, просто бессмысленны","type":"text"}]}]}},{"id":"5a8ca4eb-d92e-46c8-b889-e15c6c9d4dc2","slug":"transformer-and-diffusion","title":"Подходы к разработке: Transformer и Diffusion","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Это аналогия на два популярных вида нейросетей:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Transformer. Они работают по принципу последовательного предсказывания следующего токена после серии предыдущих. Так работают ChatGPT и другие языковые модели. То есть они последовательно слово за словом генерируют ответ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Diffusion. Такие модели работают иначе: они начинают с шума и постепенно проявляют конечный результат. По такому принципу работают генераторы картинок, проявляя из шума эти самые картинки","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"По аналогии с этим можно подходить и к разработке (например игр): ","type":"text"}]},{"type":"paragraph","content":[{"text":"Можно, как Transformer'ы делать все последовательно от начала и до конца без перескакиваний и переделок. То есть сначала всё на этапе диздока продумал, потом пошел это последовательно кодить, потом приделывать картинки от дизайнера и т.д.","type":"text"}]},{"type":"paragraph","content":[{"text":"Такой подход спасает от постоянных переделок, но оставляет риск достаточно поздно заметить фундаментальные проблемы, возникшие еще на этапе идеи, которые будут всё руинить и сильно ограничивать","type":"text"}]},{"type":"paragraph","content":[{"text":"Можно, как Diffusion'ы разрабатывать множество разных элементов и аспектов игры параллельно, постепенно \"проявляя их из шума\"","type":"text"}]},{"type":"paragraph","content":[{"text":"В таком подходе проще рано заметить какие-то фундаментальные проблемы и проще их исправить. Но самих переделок потенциально значительно больше. Также есть проблема с тем, что конечный результат даже части игры не доступен и его соответсвенно невозможно показать, пока ты не дошел до конца. Комфорт применения данного подхода в том числе сильно зависит от уровня компетенций, потому что, как минимум с позиции написания кода, понимание принципов построения более легко скейлящегося (расширяющегося) кода сильно облегчает процесс","type":"text"}]},{"type":"paragraph","content":[{"text":"Оба подхода возможны, оба подхода имеют свои компромиссы, ни один не доминирует над другим сам по себе","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Подкаст о геймдизайне с Kelin2025","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/NwnN5wZnE28?si=3arPOWhDq5-f9QU9&t=2022","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"790b77e0-8001-453b-9457-e05306acd380","slug":"functional-and-aesthetic-aspects","title":"Геймплейно-функциональный и эстетико-нарративный аспекты игр","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Все содержимое игры глобально можно поделить на два аспекта:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Геймплейно-функциональный — правила, механики, хитбоксы, системы, их взаимосвязи, игровой баланс, смысловая часть интерфейса, сам факт наличия каких-то звуковых или визуальных маркеров и другие вещи, определяющие логику игры и логику поведения игрока","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Эстетико-нарративный — весь визуал, анимации, стилистика, оформление, сеттинг, внешний вид того же интерфейса и визуальных маркеров, все звуковое оформление игры, качество текста и другие вещи, касающиеся именно того, как игра звучит, выглядит и обеспечивает повествование","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Такое разделение в том числе позволяет легко определять, где у нас действительно разные геймплейно механики, а где нет. Например эффекты отравления и горения во многих играх геймплейно представляют из себя один и тот же DOT (Damage Over Time), но эстетико-нарративно отличаются. То же относится и к разным вариантам нюков (nuke — способность наносящая разовый урон) из первых двух Mass Effect","type":"text"}]}]}},{"id":"3ae1605f-1ec0-4b98-a84c-ed31b8ee807c","slug":"challenging-difficulty","title":"Связь сложности и челленджовости","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Порог ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", после которой игрок с большой вероятностью начнёт жаловаться на духоту, ограничен её ","type":"text"},{"text":"челленджовостью","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"С момента, как повышение сложности перестаёт переводить ","type":"text"},{"text":"потенциальную челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#potential-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в ","type":"text"},{"text":"реализованную","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", перестаёт появляться новый игровой опыт и остаётся лишь механическая дрочь, с которой будет плеваться значительная доля аудитории, а оценят лишь те, кому игра невероятно заходит","type":"text"}]},{"type":"paragraph","content":[{"text":"В свою очередь, чрезмерное понижение ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" может перевести бОльшую часть ","type":"text"},{"text":"реализованной челленджовости","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#realized-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в ","type":"text"},{"text":"потенциальную","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#potential-challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" и превратить предполагаемые к постоянному использованию ","type":"text"},{"text":"механики","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в ","type":"text"},{"text":"опциональные","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}},{"id":"5eda4951-1c9e-4c54-aa82-a75cb0475911","slug":"wanna-have-fun-moment","title":"\"Хочу играть весело\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Явление, когда игрок играет нерационально в угоду фана","type":"text"}]},{"type":"paragraph","content":[{"text":"Это может быть как сознательным решением ","type":"text"},{"text":"(например, умышленно не использовать предметы)","type":"text","marks":[{"type":"italic"}]},{"text":", так и неосознанным ","type":"text"},{"text":"(игрок в пылу экшна активно спамит всеми кнопками, не замечая, что это на самом деле либо избыточно, либо вовсе бесполезно)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Стоит понимать, что с точки зрения анализа гейм-дизайна и то, и то - девиация. Если взглянуть на примеры выше:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Сознательное, скорее всего, единичный случай, который не имеет особо смысла разбирать","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"А под неосознанное нужно адаптировать гейм-дизайн так, чтобы это было оптимально. Чтобы и рациональный игрок не свалился в одну кнопку и не начал скучать","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"Весёлый\" геймплей должен вознаграждаться","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#fun-should-be-rewarded","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Адвокат Supergiant Russia критикует мой обзор Hades","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/WBTeef9tI3M","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"071773b6-87d6-49d0-baa3-baec720ede78","slug":"neko-mario-moment","title":"\"Neko Mario\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Neko Mario","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.nekomario.com/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" ","type":"text"},{"text":"(или Cat Mario)","type":"text","marks":[{"type":"italic"}]},{"text":" - фанатская версия Mario, в которой на каждом шагу встречаются крысиные ловушки, избежать которые можно, лишь предварительно о них зная","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, перед ямой, через которую нужно перепрыгнуть, будет невидимый низкий потолок. Или может провалиться пол, причём таким образом, что если на него наступить, то падения не избежать","type":"text"}]},{"type":"paragraph","content":[{"text":"\"Neko Mario\" moment","type":"text","marks":[{"type":"bold"}]},{"text":" обычно используется, когда подобный троп встречается в игре, которая не позиционирует себя как игра на потроллить","type":"text"}]},{"type":"paragraph","content":[{"text":"Запуская ","type":"text"},{"text":"Neko Mario","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.nekomario.com/syobon.html","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", игрок заранее готов к тому, что здесь его будут всячески разводить. И ему будет интересно, как его разведут на этот раз. Если же такое внезапно встречается в обычной игре, фидбеком зачастую будет \"ну и зачем это было?\"","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Дизайн должен быть последовательным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#design-should-be-consistent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"6aac0e26-c34f-4e51-b105-4c2b043714f5","slug":"design-should-be-consistent","title":"Дизайн должен быть последовательным","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Логика работы ","type":"text"},{"text":"механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" и баланс ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" должны быть реализованы таким образом, чтобы синергировать друг с другом и работать на какую-то идею, а не противоречить друг другу","type":"text"}]},{"type":"paragraph","content":[{"text":"Распространённой ошибкой в гейм-дизайне является расхождение в ответах на вопросы ","type":"text"},{"text":"\"что мы хотим от игрока\"","type":"text","marks":[{"type":"italic"}]},{"text":" и ","type":"text"},{"text":"\"за что мы хотим его наказывать\"","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"К примеру, мы берём за основу предположение ","type":"text"},{"text":"\"агрессивный геймплей - это круто\"","type":"text","marks":[{"type":"italic"}]},{"text":". Соответственно, мы даём игроку большой набор агрессивных инструментов, даём им какие-то сочные анимации и звуки, доставляющие удовольствие при каждом их прожатии. Но затем сильно наказываем за каждое проявление агрессии, потому что игрок якобы слишком силён. В результате игрок будет играть пассивно - от защиты, выжидания итд. Поскольку мы дизайнили игру, предполагая агрессивный геймплей, пассивный выходит неинтересным","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот - если в такой игре мы хотим добиться ","type":"text"},{"text":"сложности","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" в значении X, но сохранить геймплей интересным, то куда разумнее не добавлять противнику штуки вроде контактного урона, спонтанных парирований итд, а добиться этого другими решениями. Даже банальное увеличение здоровье врагу на такое значение, чтобы ","type":"text"},{"text":"сложность","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" добралась до X засчёт остальных ошибок, будет веселее. Ведь так игрок всё ещё потратит на босса X попыток, но будет играть через задуманный \"интересный\" стиль","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"Happy hob\" moment","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#happy-hob-moment","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"ad10f6c5-60b0-4f40-a7c4-029437274bea","slug":"expanding-satisfaction","title":"Расширение диапазона довольных игроков","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Любой разработчик заинтересован в том, чтобы его игра смогла охватить и удовлетворить как можно более широкий пласт игроков среди потенциальной целевой аудитории игры. Не только с точки зрения повышения доходов и известности, но и в том числе творческой самореализации","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему там, где есть возможность расширить диапазон довольных игроков ","type":"text"},{"text":"без ущерба текущей аудитории","type":"text","marks":[{"type":"bold"}]},{"text":", это стоит сделать","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 1. Assist-режимы и варианты сложности","type":"text"}]},{"type":"paragraph","content":[{"text":"Есть множество игр, геймплей которых раскрывается именно на высокой сложности (см. ","type":"text"},{"text":"связь сложности и челленджовости","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenging-difficulty","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":")","type":"text"}]},{"type":"paragraph","content":[{"text":"Такие игры, однако, могут иметь и составляющие, которые представляют интерес безотносительно сложности","type":"text"}]},{"type":"paragraph","content":[{"text":"Также есть люди, которые могли бы проникнуться игрой, но без нормальной кривой обучения не успеют набрать критическую массу заинтересованности, чтобы решить, что оно стоит того","type":"text"}]},{"type":"paragraph","content":[{"text":"В таких случаях имеет смысл рассмотреть такие решения как: варианты/кастомизация сложности, ассист-режимы ","type":"text"},{"text":"(таргетное упрощение/отключение определённых механик)","type":"text","marks":[{"type":"italic"}]},{"text":", сюжетный режим ","type":"text"},{"text":"(на случай, если в игре есть стоящий внимания сюжет)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Примеры из игр","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"SIFU","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2138710/Sifu/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" есть механика старения - после смерти персонаж возрождается, но стареет, а по достижению определённого возраста ты не можешь продолжать. По сути это один большой HP-бар на всю игру, вынуждающий идеально пройти предыдущие миссии перед заходом на следующие. Несмотря на то, что как маркетинговый гиммик эта механика привлекла внимание, дальше второго босса ушло лишь 30% игроков. Тем временем, последнего босса в ","type":"text"},{"text":"Streets of Rage 4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/985890/Streets_of_Rage_4/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" прошло 35%. Ачивки, подразумевающие повторное прохождение, также имеют довольно высокий %. Таким образом, полноценным прохождением ","type":"text"},{"text":"SoR4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/985890/Streets_of_Rage_4/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" насладился бОльший процент игроков, а ценителей хардкора игра не оттолкнула. Впоследствии в ","type":"text"},{"text":"SIFU","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/2138710/Sifu/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" добавили вариант сложности с отключённой механикой старения","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Источники статистики: ","type":"text"},{"text":"SIFU","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.trueachievements.com/game/Sifu/achievements","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", ","type":"text"},{"text":"Streets of Rage 4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.trueachievements.com/game/Streets-of-Rage-4/achievements","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nine Sols","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1809540/Nine_Sols/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - метроидвания с довольно сложной боёвкой и боссами. В ней так же есть сюжетный режим. Так, ценители боёвки пойдут в обычный режим, и их опыт никак не изменится; а более казуальная аудитория всё ещё насладится историей без душки от сложных боссфайтов","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Celeste","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/504230/Celeste/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" - precision-платформер, в котором есть как плавный порог вхождения, так и assist-режим, упрощающий и даже отключающий некоторые механики. Игра имеет отличные продажи, 97% положительных отзывов, а также даже спустя 7 лет после релиза находится в первой строчке популярных игр на ","type":"text"},{"text":"speedrun.com","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.speedrun.com/games","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" и огромное количество хардкорных модов","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 2. Реактивные vs проактивные игроки","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Реактивные игроки склонны использовать только рациональные механики, игнорируя остальные. Если в игре слишком много ","type":"text"},{"text":"опциональных механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" и/или именно они являются наиболее интересными и увлекательными по сравнению с рациональными, то это ухудшит игровой опыт для данной категории игроков. Потому что их геймплей будет склоняться к чему-то скучному, но практичному","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Проактивные игроки не против использовать и ","type":"text"},{"text":"опциональные механики","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#optional-mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", если те покажутся им весёлыми. Их игровой опыт будет одинаково удовлетворительным при любом соотношении механик","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Таким образом, у реактивных игроков есть потребность в том, чтобы в игре было как можно больше качественных рациональных механик. Тогда как у проактивных игроков противоположной потребности в нерациональных механиках нет - для них этот момент безразличен","type":"text"}]},{"type":"paragraph","content":[{"text":"Посему повышение рациональности механик игры до достаточного уровня сделает реактивных игроков довольными, никак при этом не навредив проактивным","type":"text"}]}]}},{"id":"a5aab868-d651-4ab3-bedb-aa74ec833c6f","slug":"dont-hide-what-is-already-known","title":"Не скрывай информацию, если она уже известна","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Многие игры скрывают от игрока часть информации, и это может иметь свою пользу. Например, чтобы не нагружать игрока лишней информацией в начале игры, можно не показывать игроку некоторые вкладки интерфейса до тех пор, пока они не понадобятся","type":"text"}]},{"type":"paragraph","content":[{"text":"В то же время, если игрок в процессе игры узнает какую-то информацию, то нет смысла её продолжать скрывать - польза ","type":"text"},{"text":"(как с точки зрения геймплея, так и с точки зрения порога вхождения)","type":"text","marks":[{"type":"italic"}]},{"text":" исчезает, и дальнейшее сокрытие переходит в разряд проблемы ","type":"text"},{"text":"QoL","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#quality-of-life","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]},{"type":"paragraph","content":[{"text":"Примеры","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"The Binding of Isaac","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/113200/The_Binding_of_Isaac/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" долгое время отсутствовало описание предметов. В первый раз это, хоть и вредит принятию решений, но имеет и пользу - чтобы игрок тыкнулся в новый предмет и получил какой-то вау-эффект, какую-то новую игровую ситуацию. Во второй раз из этого сокрытия информации не следует ничего, кроме того, что игрок должен держать в голове каждый из тысячи увиденных предметов, в одной из сотен игр, в которые он играет, в жизни, полной информации","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В ","type":"text"},{"text":"Hollow Knight","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/367520/Hollow_Knight/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" карта каждой локации становится видна только после её покупки, даже если у игрока есть перо (предмет, рисующий карту) и он уже пробежал всю локацию. Опять же, при первом прохождении локации это имеет смысл - мы создаём неизвестность и хотим, чтобы игрок потыкал каждый уголок сам; чтобы пошёл, куда захочет, а не ровно туда, где лежат самые ценные секреты/основной сюжет/итд. Во второй же заход нам уже нечего оберегать - это лишь породит путаницу \"а где была вот эта хрень\" и потратит лишнее время на плутание по локации, в которой не происходит ничего нового","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В The Binding of Isaac добавили описание предметов","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/news/app/250900/view/521976260528701584","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"19147101-3ef2-4ae4-a215-3545c6aba6a0","slug":"happy-hob-moment","title":"\"Happy hob\" moment","category":"moments","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Ситуация, при которой игрок, вместо ведения активного боя, играет максимально пассивно и безопасно, порой доходя до того, что удар наносится строго в одно максимально стабильное окно","type":"text"}]},{"type":"paragraph","content":[{"text":"Названа в честь одноимённого no-hit раннера ","type":"text"},{"text":"The Happy Hob","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/channel/UC0E1n0GRgBW5gR7y7H9TjZQ","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]},{"type":"paragraph","content":[{"text":"Эта ситуация свойственна плохо задизайненным боевым системам, в которых игроку дают какой-то арсенал инструментов, но баланс угрозы и выгоды от их использования хуже, чем при стиле игры happy hob","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Дизайн должен быть последовательным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#design-should-be-consistent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"643adf79-baf9-40df-ab05-905460a66f44","slug":"marketing-promise","title":"Маркетинговое обещание","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Вся публично доступная информация со стороны разработчика, формирующая у игрока ожидания того или иного игрового опыта","type":"text"}]},{"type":"paragraph","content":[{"text":"К маркетинговому обещанию можно отнести:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Трейлеры","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Описание игры на странице в магазине","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Эстетико-нарративные элементы, подразумевающие определённый геймплей ","type":"text"},{"text":"(например, персонаж, выглядящий как варвар, создаёт ожидание битвы \"напролом\")","type":"text","marks":[{"type":"italic"}]}]}]}]},{"type":"paragraph","content":[{"text":"Расхождение итогового игрового опыта с ожиданием является либо провалом маркетинга ","type":"text"},{"text":"(рекламировали шутер, а игра - стелс-хоррор)","type":"text","marks":[{"type":"italic"}]},{"text":", либо неудачными решениями в гейм-дизайне ","type":"text"},{"text":"(варвар оказался ваншотным)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Отличие маркетиногового обещания от задумки автора в том, что маркетинговое обещание игроку демонстрируют публично и разночтения исключены. Тогда как апелляция к задумке автора зачастую являются лишь спекуляцией в попытках объяснить, почему геймплей вышел таким, какой он есть","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Автор - мёртв","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#author-is-dead","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"55ad0f3c-9e1a-463b-80ee-8fac439025e3","slug":"a-purpose-of-a-system-is-what-it-does","title":"Суть системы в том, что она делает","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Иногда люди ","type":"text"},{"text":"(как разработчики, имеющие какую-то задумку, так и игроки понравившихся продуктов)","type":"text","marks":[{"type":"italic"}]},{"text":" при обсуждении какой-то неинтуитивной или нерабочей системы начинают объяснять, в чём её \"суть\" - как она работает, что игрок пропустил и так далее","type":"text"}]},{"type":"paragraph","content":[{"text":"На самом деле, касается не только обсуждения. Часто у гейм-дизайнера может замылиться глаз - например, он во время тестов будет прокачивать персонажа в рогалике, а потом выяснится, что игра абсолютно спокойно проходится с полным игнором прокачки ","type":"text"},{"text":"(тру стори из девлога, кстати)","type":"text","marks":[{"type":"italic"}]},{"text":". И они могут даже реализовать в игре подробный туториал о том, как делать такую-то штуку, а по итогу окажется, что штука нахрен не нужна","type":"text"}]},{"type":"paragraph","content":[{"text":"Так вот","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нет смысла напоминать, что суть системы в X, если она проваливает X. Если игрок не увидел важную дверь в тёмном дальнем углу - наверное, нужно её куда-то передвинуть или выделить","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Нет смысла объяснять, как красиво можно комбинировать приёмы и протезы в условной Sekiro, если игрок всё это скипнул из-за расходного ресурса и сомнительной полезности","type":"text"}]}]}]}]}},{"id":"48a7dc93-23ca-424a-a5eb-46a74dc36c28","slug":"player-goals","title":"Про целеполагание игрока","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Анализ строится от препозиции, что цель игрока при запуске ","type":"text"},{"text":"игры","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#game","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" - получить от неё удовольствие","type":"text"}]},{"type":"paragraph","content":[{"text":"Следствия и примечания","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Первые часы в игре крайне важны, чтобы завлечь игрока. Иначе он просто уйдёт ","type":"text"},{"text":"\"получать удовольствие\"","type":"text","marks":[{"type":"italic"}]},{"text":" в другую игру","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В целях получения удовольствия, игрок может давать игре небольшие уступки. Например, умышленно игнорировать совсем чизовые стратегии, аннулирующие игровые ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". Или закрывать глаза на объективную слабость субъективно понравившихся ","type":"text"},{"text":"механик","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". Однако, чем больше общий объём таких уступок, тем меньшее удовлетворение игрок в конечном счёте получит. Поскольку игроку вместо получения интересного игрового опыта \"из коробки\" придётся додумывать гейм-дизайн за разработчика, при этом осознавая, что все его сверхусилия на самом деле не необходимы и не поощряются игрой","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"См. ","type":"text"},{"text":"Весёлый геймплей должен быть рациональным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#fun-should-be-rewarded","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Для игр/разработчиков с высокой репутацией и популярностью игроки, как правило, дают гораздо больше уступок. В таких случаях не стоит принимать ярко положительный отзыв как сигнал о том, что с гейм-дизайном в игре всё отлично. Зачастую людям нравятся такие игры не \"благодаря\", а \"вопреки\" определённым решениям. И как бы такие люди ни заявляли обратного, другие игры, которые повторяют проблемные решения, оказываются либо завалены негативными отзывами, либо в принципе остаются незамеченными","type":"text"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Тотальное оказуаливание и/или удаление каких-либо плохо задизайненных сложных игровых сегментов не является решением для удовлетворения игрока. Поскольку мы в таком случае удаляем геймплей и удовольствие не от чего получать. Посему любое предложение в духе ","type":"text"},{"text":"\"удалить из игры контактный урон\"","type":"text","marks":[{"type":"italic"}]},{"text":" подразумевает не только удаление оного, но и доработку остальных игровых систем таким образом, чтобы избавиться от проблемных решений, но всё ещё предоставить текущему игроку сопоставимый по сложности контент","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Такие цели как ","type":"text"},{"text":"\"пройти игру без урона\"","type":"text","marks":[{"type":"italic"}]},{"text":", ","type":"text"},{"text":"\"пробежать её как можно быстрее\"","type":"text","marks":[{"type":"italic"}]},{"text":", ","type":"text"},{"text":"\"научиться проходить игру красиво\"","type":"text","marks":[{"type":"italic"}]},{"text":" и прочие ","type":"text"},{"text":"челленджи","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challenge","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" не рассматриваются, если игра сама не предполагает такой цели и не вознаграждает за это","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Может показаться, что этот принцип расходится с ","type":"text"},{"text":"рациональным агентом","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#rational-agent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". На самом деле это не так. Связь рационального агента и данного принципа стоит расценивать следующим образом: игрок будет действовать рационально в большинстве случаев, но иногда может отсечь некоторые опции, если те уничтожают геймплей. При этом, в рамках оставшихся опций геймплей всё ещё будет стремиться к рациональному. И даже в таких случаях большинство игроков скорее всего всё ещё будут играть рациональными опциями, ничего не отсекая ","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Например, несмотря на то, что знак Странницы и заклинание \"Буйство Нитей\" в Silksong являются самыми рациональными И самыми геймплейно примитивными опциями, они всё равно были топ 1 выбором игроков с огромным отрывом. См. статистика ","type":"text"},{"text":"по знакам","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://t.me/kelin2play/1361","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" и ","type":"text"},{"text":"заклинаниям","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://t.me/kelin2play/1413","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}]}]}},{"id":"fc90d17f-b545-426d-9522-b6b7f9f6e173","slug":"ideal-game","title":"Идеальная игра","category":"terms","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Игра","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#game","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":", которую нельзя сделать лучше","type":"text"}]},{"type":"paragraph","content":[{"text":"Выражается в виде","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Отсутствия противоречий между элементами, упущений в презентации системы и прочих ошибок","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Исчерпания возможностей добавить новый элемент, не породив противоречий","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Исчерпания возможностей провести синергию между существующими элементами системы","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Диапазон довольных игроков","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#expanding-satisfaction","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" невозможно расширить без вреда уже существующей аудитории","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примечания","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Два синергирующих друг с другом процесса будут однозначно лучше двух несвязанных ","type":"text"},{"text":"(см. ","type":"text","marks":[{"type":"italic"}]},{"text":"Онтологический принцип холизма","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://ru.wikipedia.org/wiki/%D0%A5%D0%BE%D0%BB%D0%B8%D0%B7%D0%BC","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}},{"type":"italic"}]},{"text":")","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Возможности для добавления новых элементов и проведения синергий достаточно широки. Однако, они не приведут к реализации всего в одной игре. Каждое последующее добавление нового элемента отсекает другие, которые противоречат ему. Таким образом, из бесконечного множества любых возможных механик вырисовывается конечное множество, которое не может быть далее расширено","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Например, добавление гоночных автомобилей в ","type":"text"},{"text":"Elden Ring","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/1245620/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":" не сделает игру лучше. Поскольку, в таком случае, текущие игроки получат совершенно левый для них контент, который, к тому же, будет мешать/отвлекать от взаимодействия остальным","type":"text"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\"Безыдейные, стерильные, ведущие во всём за ручку\"","type":"text","marks":[{"type":"italic"}]},{"text":" и прочие отсылающие к играм Ubisoft эпитеты не относятся к идеальным играм по четвёртому критерию","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Платформер, в котором нет никаких противоречий, есть внятный туториал, он максимально богат механически, синергии исчерпаны, но все действия в нём нужно совершать с невозможной для человека скоростью/реакцией ","type":"text"},{"text":"(т.е. он де факто непроходим)","type":"text","marks":[{"type":"italic"}]},{"text":", не является идеальной игрой, поскольку диапазон довольных игроков в таком случае равен нулю, а невозможные тайминги противоречат задаче в них попадать","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Примеры игр, близких к идеалу: Portal 2, Into the Breach, Devil Daggers, Spelunky, Baba is You","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Идеал недостижим, но к нему можно стремиться","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#strive-for-perfection","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"4a1572c1-5001-48df-b1f1-2f9541867e6f","slug":"setting-and-story-is-not-an-excuse","title":"Нарратив не должен жертвовать геймплеем","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Практически любую идею можно обыграть так, чтобы было и \"прикольно\" с точки зрения \"обыграть сеттинг/нарратив\", и чтобы не мешало игроку","type":"text"}]},{"type":"paragraph","content":[{"text":"Например, в ","type":"text"},{"text":"Hollow Knight: Silksong","type":"text","marks":[{"type":"bold"}]},{"text":" есть суп, повышающий скорость атаки. Но восполняются запасы только в конкретном месте ","type":"text"},{"text":"(где сидит группа блох)","type":"text","marks":[{"type":"italic"}]},{"text":". С точки зрения нарратива это обосновано - мол, блохи варят суп, вот ты к ним приходишь за добавкой. Но с точки зрения геймплея это означает, что на закрепном боссе ты будешь вынужден периодически уходить, чтобы пополнить запасы. При этом, с точки зрения нарратива ничто не мешало разработчику обыграть это иначе - мол, ты спас наших блох, в награду с тобой пойдёт одна из них, и пусть она варит этот суп на скамейке-чекпоинте. Нарративно всё ещё \"прикольно\", но геймплейно в разы менее душно","type":"text"}]},{"type":"paragraph","content":[{"text":"Над нарративом и над геймплеем работает команда. И они согласовывают все составляющие игры. Поэтому, если какое-то решение является проблематичным с точки зрения гейм-дизайна, нарратив не является тому оправданием - его можно и подкорректировать, чтобы получить в целом менее противоречивый продукт","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Игры - про геймплей","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#games-are-about-gameplay","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"6d84d23a-4d37-43c6-a4f2-31ffed3943fe","slug":"player-expression-vs-enemy-expression","title":"Player expression vs enemy expression","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Две характеристики боевых систем, определяющие степень комплексности и разнообразия на стороне игрока и на стороне противников соответственно","type":"text"}]},{"type":"paragraph","content":[{"text":"Простым словами - насколько игра даёт разгуляться игроку/противникам в плане действий, их комбинаций итд.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Высокий player expression: ","type":"text"},{"text":"Devil May Cry","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/601150/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]},{"text":", ","type":"text"},{"text":"ULTRAKILL","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1229490/ULTRAKILL/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Высокий enemy expression: ","type":"text"},{"text":"Elden Ring","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/agecheck/app/1245620/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Высокий player+enemy expression: ","type":"text"},{"text":"Nioh","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/485510/Nioh_Complete_Edition/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Примечания","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Обе характеристики могут варьироваться в пределах одной игры ","type":"text"},{"text":"(например, мобы - простые болванчики, а боссы с комплексным поведением)","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"От этих характеристик напрямую зависит ","type":"text"},{"text":"челленджовость","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#challengeness","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":" игры","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Максимизируя обе характеристики сразу, можно создать продукт с высоким потолком мастеринга, но с большой вероятностью высоким окажется и порог входа","type":"text"}]}]}]}]}},{"id":"c456fb63-5bd8-4a44-ac56-4d2df6166410","slug":"intent-over-inputs","title":"Намерения игрока важнее инпутов","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Игры, которые воспринимаются игроками как \"честные\", на самом деле делают огромное количество незаметных поблажек в их пользу","type":"text"}]},{"type":"paragraph","content":[{"text":"Делается это не для того, чтобы игры оказуалить. А для того, чтобы когнитивные ресурсы игрока были свободны для более комплексных и интересных задач, а более тривиальные не руинили задуманный игроком план их решения","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример: Input buffering","type":"text"}]},{"type":"paragraph","content":[{"text":"Предположим, есть некий экшн-рогалик с довольно активной боёвкой, и у игрока есть некая заряжаемая атака из лука. У этой атаки есть небольшой интервал отката ","type":"text"},{"text":"(в районе 100мс)","type":"text","marks":[{"type":"italic"}]},{"text":", чтобы стрельба шла с определённой периодичностью, а не одна стрела за другой","type":"text"}]},{"type":"paragraph","content":[{"text":"В такой игре игрок будет погружён в сражения с врагами. И он не будет думать о том, чтобы нажимать кнопку строго после завершения времени отката. Он будет думать о том, что ","type":"text"},{"text":"сейчас он выстрелит вот в этого врага, а потом вот в того, а потом побежит туда-то","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"И если не добавить буффер, который при зажатии кнопки во время отката запоминал бы это нажатие и при откате засчитывал использование атаки, то у игрока просто периодически не будет срабатывать выстрел, и это в конечном счёте его задушит. Причём, вполне вероятно, что игрок даже не поймёт, в чём было дело - подумает, что в игре инпуты кривые и не засчитываются, и оставит отрицательный отзыв","type":"text"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"text":"К таким поблажкам можно отнести","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Время койота, jump buffer'ы и аналогичные решения, сглаживающие неидеально прожатые кнопки","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Добивание противника в случаях, когда атака оставила ему 1 HP","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"итд.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Почему Celeste - один из лучших платформеров последних лет","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/watch?v=ilJ3vHSaJtg","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Разбор косяков платформинга в Blasphemous","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.youtube.com/watch?v=0KPhhWB1z14","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Момент с AMA xkoster об этом же","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/_ZiTfc_urXQ?t=7528","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]}]}},{"id":"a954e6f3-44bf-4c1c-9eba-8e7db846a2ad","slug":"rules-should-serve-a-purpose","title":"Правила подбираются под цели","category":"design_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"То, какой вариант реализации механик, систем, ограничений и поощрений лучше подойдёт для игры в целом зависит от того, какой целевой игровой опыт мы хотим смоделировать","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 1: Высокий vs низкий ТТК в шутере","type":"text"}]},{"type":"paragraph","content":[{"text":"Если цель - ","type":"text"},{"text":"\"для убийства противника нужно совершать какие-то комбинации действий вместе с командой\"","type":"text","marks":[{"type":"italic"}]},{"text":", то, скорее всего, лучше подойдёт высокий","type":"text"}]},{"type":"paragraph","content":[{"text":"Если цель - ","type":"text"},{"text":"\"сделать тактическое позиционирование важным\"","type":"text","marks":[{"type":"italic"}]},{"text":", то, наверное, низкий","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Пример 2: Наличие vs отсутствие контактного урона","type":"text"}]},{"type":"paragraph","content":[{"text":"Если мы хотим от игрока, чтобы он концентрировал внимание на перемещении врага и старался держать дистанцию, то наличие контактного урона сыграет на руку","type":"text"}]},{"type":"paragraph","content":[{"text":"Если мы хотим, чтобы игрок не боялся приближаться к врагу и не тратил слишком много внимания на перемещение противника, то лучше будет не добавлять контактный урон","type":"text"}]},{"type":"paragraph","content":[{"text":"См. также:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Полезность механики зависит от контекста","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics-in-vacuum","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Дизайн должен быть последовательным","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#design-should-be-consistent","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}},{"id":"039e55ed-8524-4fa0-b157-95141d8ab430","slug":"author-is-dead","title":"Автор - мёртв","category":"analysis_principles","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Конечный вид игры и её восприятие игроками важнее любых оправданий о замысле разработчика или причинах, по которым он сделал X так, а не иначе. Это не говоря уж о том, что за ","type":"text"},{"text":"\"задумкой автора\"","type":"text","marks":[{"type":"italic"}]},{"text":" нередко скрываются спекуляции - додумки, для чего автор сделал X","type":"text"}]},{"type":"paragraph","content":[{"text":"Есть, однако, исключение под названием ","type":"text"},{"text":"\"","type":"text","marks":[{"type":"italic"}]},{"text":"маркетинговое обещание","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#marketing-promise","class":"text-blue-500 hover:text-blue-700 underline","target":""}},{"type":"italic"}]},{"text":"\"","type":"text","marks":[{"type":"italic"}]},{"text":". Если игру всем видом продают как мясной шутер, а на самом деле в неё нужно играть как в стелс иммерсив сим, прибегая к стрельбе лишь в крайних случаях - в таком случае, будет неудивительно, если аудитория мясных шутеров будет пытаться играть в это как в мясной шутер и скажет, что это хреновый мясной шутер. Это уже не проблема гейм-дизайна, это проблема маркетинга","type":"text"}]}]}},{"id":"312d4ff3-2b75-4420-ac80-ce9a5760135f","slug":"input-vs-output-random","title":"Input vs Output Random","category":"classifications","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Input random","type":"text","marks":[{"type":"bold"}]},{"text":" - случайность, которая влияет на начальные условия или доступные опции ","type":"text"},{"text":"(например, выпадение предметов, генерация уровня)","type":"text","marks":[{"type":"italic"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Output random","type":"text","marks":[{"type":"bold"}]},{"text":" - случайность, которая влияет на результат уже принятого решения ","type":"text"},{"text":"(например, шанс попадания или крита)","type":"text","marks":[{"type":"italic"}]}]}]}]}]}},{"id":"c9f9a9c3-63ff-4ed0-91ab-1eec2f22c913","slug":"constructor-building-systems","title":"Конструктор (класс систем строительства)","category":"classifications","content":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Сразу важные оговорки:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Строительство в играх обычно называют либо слишком узко ","type":"text"},{"text":"(“заводостроение”)","type":"text","marks":[{"type":"italic"}]},{"text":", либо сваливают всё под абстрактное слово ","type":"text"},{"text":"“песочница”","type":"text","marks":[{"type":"italic"}]},{"text":". Из-за этого трудно понять, почему условные Factorio, Reassembly и Poly Bridge принадлежат к одному общему классу механик, а обычное строительство в Minecraft устроено принципиально иначе.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"“Конструктор”","type":"text","marks":[{"type":"bold"}]},{"text":" — это класс систем строительства, где суть заключается в ","type":"text"},{"text":"инженерном решении задач через сборку","type":"text","marks":[{"type":"bold"}]},{"text":". Здесь постройка — не декорация или «домик для красоты», а рабочий механизм под конкретную цель в конкретных условиях.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ни один из подклассов конструктора не лучше и не хуже других","type":"text","marks":[{"type":"bold"}]},{"text":". Каждый из них решает свои задачи, а в одной игре могут встречаться сразу несколько подклассов (например, в TerraTech есть черты всех трех, а в Minecraft конструктор присутствует локально в виде редстоуна).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Эстетическое творчество и декор","type":"text","marks":[{"type":"bold"}]},{"text":" (когда игрок строит просто ради внешнего вида) — это отличная альтернативная активность, но она не определяет качество самого конструктора. Качество конструктора оценивается по тому, насколько интересно собирать работающие структуры и насколько осмысленны ограничения.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Что такое конструктор простыми словами:","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Это система, где ты собираешь механизм из ","type":"text"},{"text":"функциональных деталей","type":"text","marks":[{"type":"bold"}]},{"text":" (у каждого блока есть практическая роль: двигатель везет, пушка стреляет, генератор дает энергию, конвейер везет ресурсы) и соединяешь их по правилам и ограничениям, чтобы выполнить конкретную задачу в конкретных условиях (победить врага, наладить логистику, выдержать вес транспорта).","type":"text"}]},{"type":"paragraph","content":[{"text":"Если убрать правила соединения и ограничения — комбинаторика исчезает, и игра превращается просто в свободное перекладывание блоков.","type":"text"}]},{"type":"paragraph","content":[{"text":"Обязательные критерии:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Есть комбинаторика:","type":"text","marks":[{"type":"bold"}]},{"text":" игроку действительно нужно думать над подбором, сочетанием и компоновкой деталей.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Все детали функциональны:","type":"text","marks":[{"type":"bold"}]},{"text":" нет блоков «просто так», каждый блок делает что-то практически полезное в геймплее.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Позиция деталей имеет значение:","type":"text","marks":[{"type":"bold"}]},{"text":" важно, как именно соединены модули (спрятан ли хрупкий реактор за броней, хватает ли коннекторов, замкнута ли логистическая сеть).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Есть ограничения на соединение:","type":"text","marks":[{"type":"bold"}]},{"text":" нехватка точек крепления, лимит веса, форма блоков или требования к питанию заставляют искать компромиссы.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Детали взаимодействуют друг с другом:","type":"text","marks":[{"type":"bold"}]},{"text":" хотя бы часть элементов вырабатывает или передает ресурсы/сигналы другим деталям.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Сами подклассы:","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Технический конструктор","type":"text","marks":[{"type":"bold"}]},{"text":" — вы собираете мобильную или стационарную машину (корабль, робота, танк), чтобы напрямую взаимодействовать с окружающим миром: сражаться, исследовать карту, собирать ресурсы.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reassembly","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/329130/Reassembly/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"TerraTech","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/285920/TerraTech/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Avorion","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/445220/Avorion/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если:","type":"text"},{"type":"hardBreak"},{"text":"Например:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Форма и компоновка машины критически влияют на бой и выживание (тяжелая броня спереди, прикрытые двигатели сзади, правильные секторы обстрела орудий)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Окружающий мир и враги тоже собраны из конструктора: игрок наглядно видит примеры рабочих сборок и может тактически отстреливать опасные орудия или слабые модули врагов без скриптовых надстроек","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"В игре есть разнообразные условия среды (гравитация, перегрев, холод, агрессивная местность), заставляющие адаптировать и переделывать машины","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Заводостроительный конструктор","type":"text","marks":[{"type":"bold"}]},{"text":" — вы строите производственные цепочки и логистику, где цель — добывать, перевозить, перерабатывать ресурсы и пускать их на дальнейшее расширение и оборону.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Factorio","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/427520/Factorio/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mindustry","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1127400/Mindustry/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если:","type":"text"},{"type":"hardBreak"},{"text":"Например:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Решение логистических задач приносит кайф: проектирование транспортных развязок, балансировка потоков ресурсов, устранение узких мест на линиях снабжения","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Есть постоянный стимул развивать производство: добытые ресурсы сразу требуются для патронов, науки или экспансии, а не просто складируются в ящиках","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Пространственные ограничения и топология карты заставляют оптимизировать и компактно упаковывать производственные линии","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Пазл-конструктор","type":"text","marks":[{"type":"bold"}]},{"text":" — вы строите конструкцию под разовую техническую или логическую задачу со строго заданными условиями и требованиями.","type":"text"}]},{"type":"paragraph","content":[{"text":"Примеры игр:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Poly Bridge","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/367450/Poly_Bridge/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sunshine Heavy Industries","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://store.steampowered.com/app/1542810/Sunshine_Heavy_Industries/","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Minecraft (логические схемы на Redstone)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Реализован хорошо, если:","type":"text"},{"type":"hardBreak"},{"text":"Например:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"У задачи есть множество разных рабочих решений: от дешевых конструкций «на соплях» до идеальных и сверхэффективных инженерных шедевров","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Правила и симуляция честные и прозрачные: всегда сразу понятно, почему мост обрушился или где именно в логической цепи застрял сигнал","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Что делает конструктор крутым, а что его убивает:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ограничения соединения спасают от «схлопывания» геймплея: ","type":"text","marks":[{"type":"bold"}]},{"text":"если в игре нет жестких правил и ограничений на компоновку, геймплей схлопывается в одну доминирующую стратегию. В космическом конструкторе Avorion почти не было ограничений на соединение блоков — в итоге идеальной формой корабля стал сплошной летающий кирпич/куб. Он собирается за минуту, защищен со всех сторон, максимально маневренен, и в результате ","type":"text"},{"text":"геймплей схлопнулся","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#gameplay-collapse","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]},{"text":". Грамотные ограничения заставляют игрока искать нетривиальные инженерные компромиссы.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Баланс комбинаторики: ","type":"text","marks":[{"type":"bold"}]},{"text":"комбинаторика растет как от числа деталей, так и от правил их стыковки. Если правил нет — получается песочница без челленджа. Если ограничений слишком много — у игрока плавится мозг. Отличный конструктор держит золотую середину: понятные блоки, но глубокие правила их компоновки.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Взаимная утилизация мира и конструктора: ","type":"text","marks":[{"type":"bold"}]},{"text":"окружающий мир должен использовать конструктор (враги состоят из тех же деталей), а конструктор — механики мира (физика, среда). Игроку не нужны обучающие мануалы: он видит врага с бронированным лбом и открытыми двигателями сзади, и сам понимает, что нужно зайти ему в тыл.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Гонка технологий в мультиплеере: ","type":"text","marks":[{"type":"bold"}]},{"text":"если комбинаторики в системе достаточно, между игроками автоматически начинается соревнование сборок, шпионаж чужих идей и обмен чертежами. Разработчику даже не нужно писать для этого специальные механики.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"См. также","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Конструктор - Класс игровых систем строительства (toshibaz)","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://youtu.be/BVVxEdZkrGY","class":"text-blue-500 hover:text-blue-700 underline","target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Геймплей схлопнулся","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#gameplay-collapse","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Полезность механики зависит от контекста","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"#mechanics-in-vacuum","class":"text-blue-500 hover:text-blue-700 underline","target":""}}]}]}]}]}]}}];
  window.__KELIN_GLOSSARY__ = kelinData;
